('330cc9dea0ab0446', 'resolution of flood conmtrl', 'Bill', 'agenda_created', '', 'ORDINANCE NO. ___\n\nAN ORDINANCE RESOLUTION OF FLOOD CONMTRL\n\nBE IT ORDAINED by the Sangguniang Panlungsod, in session assembled, that:\n\nSECTION 1. Short Title. - This ordinance shall be known as the \"resolution of flood conmtrl\".\n\nSECTION 2. Declaration of Policy. - This ordinance is intended to promote public welfare, good governance, and responsive public policy.\n\nSECTION 3. Implementation. - The concerned city offices shall implement this ordinance in accordance with existing laws, ordinances, and regulations.\n\nSECTION 4. Separability. - If any provision of this measure is declared invalid, the remaining provisions shall remain in full force and effect.\n\nSECTION 5. Effectivity. - This measure shall take effect upon its approval, unless otherwise provided by law.\n\nENACTED,\n________________________\nDate: September 12, 2026', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-09-12 21:37:46.000000', '2026-09-13 19:24:37.000000', '649a3d757a6c5a0ffc32cab718be8aefd328a32934d656691eb0a5725c096c49', 'c59939d58ad69391', 'pogi', '2026-09-12 21:42:33.000000', 0, NULL, 'LIVE-RADIO-DRAMA-SKIT-COMPETITION-Year-4-Final-Mechanics (2).pdf', 162704, 'application/pdf', 'b85e780c41ee682a_LIVE-RADIO-DRAMA-SKIT-COMPETITION-Year-4-Final-Mechanics__2_.pdf', NULL, '7486bc1d2df7e69c', 'isu', '2026-09-12 21:37:55.000000', '9d555a4c2e88542fb315b9f2399cacf7737e4e201a0fe74788641113821de1d0', NULL, NULL, 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Receiving', NULL, NULL, 'LEG-2026-330CC9DEA0AB', '2026-09-12 21:37:46.000000', 'isu', 'council members', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-330CC9DE', '2026-09-12 21:37:46.000000', NULL, NULL, NULL),
('39a61b82dba9d6c4', 'sadra', 'adsfs', 'submitted_to_admin', 'Detected type\r\nSuggested title\r\nResolution on roaad\r\nDescription\r\nThis resolution addresses roaad. It aims to guide local government action and next steps.\r\nDraft text\r\nWHEREAS, Roaad..\r\n\r\nNOW, THEREFORE, BE IT RESOLVED, by the council that:\r\n1. The council hereby adopts this resolution to address roaad.\r\n2. The appropriate municipal officers are directed to take the necessary steps to implement this resolution.', '', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-07-12 09:46:01.000000', '2026-09-12 21:21:01.000000', '457471e564c47f1c37b7d60d483292376d267c0e7e1c1042a8ba1452c89532a0', 'c59939d58ad69391', 'pogi', '2026-08-01 04:37:05.000000', 0, NULL, NULL, NULL, NULL, NULL, NULL, '7486bc1d2df7e69c', 'isu', '2026-09-12 21:21:01.000000', NULL, NULL, NULL, 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Receiving', NULL, NULL, 'LEG-2026-39A61B82DBA9', '2026-07-12 09:46:01.000000', 'isu', 'council members', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-39A61B82', '2026-07-12 09:46:01.000000', NULL, NULL, NULL),
('3ee929b39e89629f', 'Republic of the Philippines City of Santiago -000-', 'Bill', 'draft', '', '<p>Republic of the Philippines City of Santiago -000-</p><p>OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSOD</p><p>EXCERPT FROM THE MINUTES OF THE 4TH REGULAR SESSION</p><p>OF THE 12TH CITY COUNCIL HELD ON AUGUST 1 1, 2025 AT SP SESSION HALL,</p><p>2ND FLOOR, CITY HALL, SAN ANDRES, SANTIAGO CITY</p><p>APPROVED UNDER SUSPENDED RULES</p><p></p><p>Sponsored by: Coun. Cassandra Eunice Sable</p><p>Co-sponsored by: Coun. Tomirose Bautista-dela Cruz Coun. Sherman A. Miguel</p><p>Coun. Anton Phoenix A. Abaya</p><p>Coun. Joan Mae V. de Jesus</p><p>Coun. Jay Arcie S. Co</p><p>Coun.Russel D. Ponce</p><p>Coun. Carlo N. de Luna</p><p>Coun.Orlando T. Chan</p><p>Coun. Benzi Tan Chai</p><p>Coun. Christopher G. Respicio</p><p>Coun. Bella M. Yodyod</p><p></p><h1>RESOLUTION NO. 12THCC-023</h1><p>AUTHORIZING THE HONORABLE CITY MAYOR, ATTY. ALYSSA SHEENA P. TAN, CPA, FOR AND ON BEHALF OF THE CITY GOVERNMENT OF SANTIAGO, TO ENTER INTO AND SIGN THE MEMORANDUM OF AGREEMENT (MOA) WITH THE COMMISSION ON POPULATION AND DEVELOPMENT REGION 11,</p><p>RELATIVE TO THE UTILIZATION OF THE 2025 RAFAEL M. SALAS KAUNLARANG PANTAO AWARD (RMSKPA) CASH GRANT</p><p>WHEREAS, the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) is a recognition and award program for institutions and individuals who have significantly contributed to the advancement of the Population and Development Agenda. With the devolution policy, the role of Local Government Units (LGUs) has been more pronounced in advancing the Philippine Population and Development Plan of Action specially in institutionalizing and localizing Population Development (POPDEV) strategies;</p><p>WHEREAS, the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) is a prestigious recognition that honors the Most Outstanding LGUs in the country for their exemplary efforts in mainstreaming and localizing the Population and Development Agenda within their local governance systems;</p><p>WHEREAS, the Philippine Population and Development Plan of Action (PPD-POA) 2023-2028 serves as the overall blueprint for inter-agency population challenges in order to accelerate the attainment of the Administration&#039;s socio-economic development agenda under PDP 2023-2028;</p><p>WHEREAS, by virtue of a Presidential and Cabinet Directive issued in 2019, the Commission on Population and Development (CPD) is directed to coordinate with relevant government agencies and LGUs for the intensified implementation of the Philippine Population and Development Program (PPDP) at all levels;</p><p>WHEREAS, the Local Government Unit of Santiago City has been adjudged as the Regional Winner of the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) — Search for the Most Outstanding LGUs in Localizing the Population and Development (POPDEV) Agenda (city category), thereby qualifying to receive a cash grant amounting to Fifty Thousand Pesos (P50,OOO.OO)•,</p><p>Page I of2 pages ofResolution No. 12thCC-02 l!åj</p><p>WHEREAS, a Memorandum of Agreement (MOA) between the City Government of Santiago and the Commission on Population and Development Region Il aims to improve the policy and program implementation at the local level and ensure localization and institutionalization of population-related strategies and interventions;</p><p>WHEREAS, under Section 8 paragraph (b) (1) (f) of Republic Act No. 7720, the City Mayor shall represent the City in all its business transactions and sign on its behalf all bonds, contracts, and obligations, and such other documents upon authority of the Sangguniang Panlungsod or under existing laws or ordinances;</p><p>WHEREFORE, on motion of Coun. Cassandra Eunice Sable, unanimously seconded, be it</p><p>RESOLVED, as it is hereby resolved, to authorize Honorable City Mayor, Atty. Alyssa Sheena P. Tan, CPA, for and on behalf of the City Government of Santiago, to enter into and sign the Memorandum of Agreement (MOA) with the Commission on Population and Development Region Il, relative to the utilization of the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) Cash Grant.</p><p>RESOLVED FURTHER, to furnish copies of this Resolution to all persons, offices, and government agencies concerned for their information and guidance.</p><p>ADOPTED. AUGUST 11, 2025.</p><p>CERTIFIED TRUE AND CORRECT:</p><p>MARY M A H. VELASCO or-s r t o the Sanggunian</p><p>ATTESTED:</p><p>A </p><p></p><p>	JAMAYNE 	LO TAN</p><p>	City Vice Mayor	residing Officer</p><p>APPROVED:</p><h1>ATTY. ALYSSA SHE NA P. TAN, CPA</h1><p>City M r</p><p>Page 2 of2 pages ofResolution No. 12thCC-023</p>', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-10-06 01:25:18.000000', NULL, 'c351e46847ffcb445570fb98a8f896afa70934096fac3f8eb61344dc4dfd1010', NULL, NULL, NULL, 0, NULL, 'R12thCC-023 MOA with the Commission on Population and Development Region II Relative to the Utilization of the 2025 Rafael M. Salas Kaunlarang Pantao Award RMSKPA Cash Grant.docx', 127525, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '560cc2cf9e634373_R12thCC-023_MOA_with_the_Commission_on_Population_and_Development_Region_II_Relative_to_the_Utilization_of_the_2025_Rafael_M._Salas_Kaunlarang_Pantao_Award_RMSKPA_Cash_Grant.docx', NULL, NULL, NULL, NULL, '036673338c5aca187cffb00488efbd9e34885fa454c714f6bfc31299b8db7f82', NULL, NULL, 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Republic of the Philippines City of Santiago -000-OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSODEXCERPT FROM THE MINUTES OF THE 4TH REGULAR SESSIONOF THE 12TH CITY COUNCIL HELD ON AUGUST 1 1, 2025 AT SP SESSION HALL,2ND FLOOR, CITY HALL, SAN ANDRES, SANTIAGO CITYAPPROVED UNDER SUSPENDED RULESSponsored by: Coun. Cassandra Eunice SableCo-sponsored by: Coun. Tomirose Bautista-dela Cruz Coun. Author: Not stated; Sponsor: Not stated.', 'Receiving', NULL, NULL, NULL, NULL, '', 'Secretariat', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-3EE929B3', '2026-10-06 01:25:18.000000', NULL, NULL, NULL),
('48907b2419840697', 'CITY COUNCIL OF METROPOLIS', 'Bill', 'approved_by_lce', '', '<p><strong>CITY COUNCIL OF METROPOLIS</strong></p><p>OFFICE OF LEGISLATIVE SERVICES  |  PROPOSED ORDINANCE NO. 2026-089</p><p><strong>ORDINANCE CREATING THE MUNICIPAL CLEAN ENERGY &amp; GREEN INFRASTRUCTURE INITIATIVE</strong></p><p><strong>SPONSOR:</strong></p><p>Councilmember Elena Rostova (District 4)</p><p><strong>CO-SPONSORS:</strong></p><p>Councilmember Marcus Vance (District 2), Councilmember Sarah Chen (At-Large)</p><p><strong>COMMITTEE REFERRAL:</strong></p><p>Committee on Health, Environment, and Public Works</p><p><strong>DATE INTRODUCED:</strong></p><p>October 12, 2026</p><p></p><p><strong>PREAMBLE &amp; LEGISLATIVE FINDINGS</strong></p><p>WHEREAS, the City of Metropolis is committed to promoting sustainable urban growth, reducing carbon emissions, and fostering environmental resilience across all municipal operations; and</p><p>WHEREAS, existing commercial and municipal energy structures contribute significantly to local greenhouse gas emissions and operational municipal expenditure; and</p><p>WHEREAS, advancing clean energy technology and implementing rooftop solar, green space integration, and energy-efficient building standards will lower long-term taxpayer expenditure and protect public health; and</p><p>WHEREAS, public consultation and environmental studies demonstrate overwhelming community support for structural sustainability reforms;</p><p><strong>NOW, THEREFORE, BE IT ORDAINED by the City Council of Metropolis as follows:</strong></p><p><strong>SECTION 1. SHORT TITLE. </strong>This Ordinance shall be known and cited as the &#039;Clean Energy and Green Infrastructure Act of 2026.&#039;</p><p><strong>SECTION 2. ESTABLISHMENT OF CLEAN ENERGY MANDATE. </strong>All newly constructed municipal buildings exceeding 10,000 square feet in footprint shall incorporate solar photovoltaic systems capable of offsetting at least 30% of estimated peak electrical load, alongside certified high-efficiency HVAC systems.</p><p><strong>SECTION 3. GREEN INFRASTRUCTURE FUND. </strong>There is hereby established a dedicated fund, designated as the &#039;Metropolis Green Infrastructure Fund,&#039; to be administered by the Department of Sustainability. The initial capital funding shall be allocated from annual municipal sustainability grants and non-tax municipal revenue sources.</p><p><strong>SECTION 4. REPORTING AND COMPLIANCE. </strong>The Director of Sustainability shall submit an annual performance report to the City Council no later than November 30 of each fiscal year, detailing energy savings, emissions reductions, and capital expenditures under this Act.</p><p><strong>SECTION 5. SEVERABILITY AND EFFECTIVE DATE. </strong>If any section or provision of this Ordinance is declared invalid by a court of competent jurisdiction, such declaration shall not affect the validity of the remaining provisions. This Ordinance shall take effect thirty (30) days following its final passage and approval.</p><p></p><p>_____________________________________Hon. Marcus VancePresident of the City Council&lt;br&gt;</p><p>_____________________________________Attest: Patricia GomezCity Clerk&lt;br&gt;</p>', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-09-27 02:38:16.000000', '2026-10-05 23:21:09.000000', '185be3bd09932c155612eee3e4d1c319a2a653e48f4188b59f003c28d89da806', 'b4f39005182a0122', 'mayor', '2026-10-05 23:21:09.000000', 0, NULL, 'Legislative_Matter_Proposed_Ordinance_2026-089-v2.docx', 38521, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '7510e0d92d7fd115_Legislative_Matter_Proposed_Ordinance_2026-089-v2.docx', NULL, '7486bc1d2df7e69c', 'isu', '2026-10-02 19:55:27.000000', 'ec8774cfc2971ff89fe9b25e15aff46dcba0741da738a7ecd6d53bc1ae60ec2d', NULL, NULL, 'Legislative Matters', 'Archived for Local Download', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, 'LCE Approved', '2026-10-05 23:21:09.000000', 'b4f39005182a0122', 'FILE - Local Offline Archive', NULL, NULL, 'CITY COUNCIL OF METROPOLISOFFICE OF LEGISLATIVE SERVICES | PROPOSED ORDINANCE NO. 2026-089ORDINANCE CREATING THE MUNICIPAL CLEAN ENERGY & GREEN INFRASTRUCTURE INITIATIVESPONSOR:Councilmember Elena Rostova (District 4)CO-SPONSORS:Councilmember Marcus Vance (District 2), Councilmember Sarah Chen (At-Large)COMMITTEE REFERRAL:Committee on Health, Environment, and Public WorksDATE INTRODUCED:October 12, 2026PREAMBLE & LEGISLATIVE FINDINGSWHEREAS, the City of Metropolis is committed to promoting sustainable urban growth, reducing carbon emissions, and fostering environmental resilience across all municipal operations; andWHEREAS, existing commercial and municipal energy structures contribute significantly to local greenhouse gas emissions and operational municipal expenditure; andWHEREAS, advancing clean energy technology and implementing rooftop solar, green space integration, and energy-efficient building standards will lower long-term taxpayer expenditure and protect public health; andWHEREAS, public consultation and environmental studies demonstrate overwhelming community support for structural sustainability reforms;NOW, THEREFORE, BE IT ORDAINED by the City Council of Metropolis as follows:SECTION 1. SHORT TITLE. Author: Not stated; Sponsor: Not stated.', 'Filing/Scan', NULL, NULL, NULL, NULL, '', 'Secretariat', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-48907B24', '2026-09-27 02:38:16.000000', NULL, NULL, NULL),
('532ac15691dedc0c', 'Republic of the Philippines', 'Bill', 'approved_by_lce', '', 'Republic of the Philippines<br><br>City of Santiago<br><br>-000-<br><br>OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSOD<br><br>EXCERPT FROM THE MINUTES OF THE REGULAR SESSION OF THE 12TH CITY COUNCIL HELD ON SEPTEMBER 29, 2025 AT AMPHITHEATER, BARANGAY HALL,<br><br>SAN ANDRES, SANTIAGO CITY<br><br>APPROVED UNDER SUSPENDED RULES<br><br>Sponsored by: Coun.Joan Mae V. De Jesus<br><br>Co-sponsored by: Coun. Cassandra Eunice Sable<br><br>Coun. Tomirose Bautista-Dela Cruz<br><br>Coun. Sherman A. Miguel<br><br>Coun. Anton Phoenix A. Abaya<br><br>Coun.Jay Arcie S. Co<br><br>Coun. Russel D. Ponce<br><br>Coun. Gino Antonio A. Siquian<br><br>Coun. Carlo N. De Luna<br><br>Coun. Orlando T. Chan<br><br>Coun. Benzi Tan Chai<br><br>Coun. Christopher G. Respicio Coun. Bella M. Yodyod<br><br>RESOLUTION NO. 12THCC-051<br><br>A RESOLUTION ENCOURAGING ALL TOURISM-RELATED ESTABLISHMENTS WITHIN THE CITY OF SANTIAGO TO ESTABLISH THEIR OWN ONE TOWN, ONE PRODUCT (OTOP) KIOSKS<br><br>WHEREAS, Republic Act No. 11960, otherwise known as the \"OTOP Philippines Act, institutionalizes the One Town, One Product Program as a national strategy to promote inclusive local economic development, support micro, small, and medium enterprises (MSMEs), and preserve cultural heritage through the advancement of community-based products and services;<br><br>WHEREAS, the Department of Trade and Industry (DTI), in partnership with local government units (LGUs), has established OTOP Hubs to serve as centralized venues for the marketing, distribution, and promotion of locally crafted goods, processed food items, and skill-based services, among others;<br><br>WHEREAS, tourism-related establishments—including but not limited to hotels, resorts, restaurants, travel agencies, and pasalubong centers—are strategically positioned to serve as platforms for showcasing the City of Santiago\'s unique local products to both domestic and international visitors;<br><br>WHEREAS, the integration of OTOP kiosks within such establishments is expected to enhance product visibility, foster cultural pride, and stimulate economic activity by providing local artisans and entrepreneurs with direct access to consumer markets;<br><br>WHEREAS, to uphold the integrity and objectives of the OTOP Philippines Program, all products to be displayed and sold in said kiosks shall be sourced exclusively from the officially designated OTOP Hub of the City, and must be supplied by duly accredited MSMEs operating within the locality;<br><br>WHEREFORE, on motion of Coun. Joan Mae V. De Jesus, unanimously seconded, be it —<br><br>RESOLVED, as it is hereby resolved, to encourage all tourism-related establishments operating within the territorial jurisdiction of the City of Santiago to establish their own One Town<br><br>One Product (OTOP) kiosks, in support of ocal e rprise development a d cultural promotion;<br><br>on No. 12t<br><br>RESOLVED FURTHER, that products to be displayed and sold in said kiosks shall be sourced from the officially designated OTOP Hub of the City, thereby ensuring quality, authenticity, and alignment with the standards and objectives of the OTOP Philippines Program;<br><br>RESOLVED FINALLY, that copies of this Resolution be furnished to the Department of Trade and Industry, the Santiago City Information, Culture and the Arts, and Tourism Office (CICATO), and all concerned tourism-related establishments for their information, guidance, and appropriate action.<br><br>ADOPTED. SEPTEMBER 29, 2025.<br><br>JESUS<br><br>RUSSE<br><br>CARL <br><br>LUNA<br><br>JESUS<br><br>RUSSE<br><br>CARL <br><br>LUNA<br><br>TOMIROSE <br><br>CRUZ<br><br>ABAYA<br><br>SIQUIAN<br><br>RESPICIO<br><br>ity <br><br>TOMIROSE <br><br>CRUZ<br><br>ABAYA<br><br>SIQUIAN<br><br>RESPICIO<br><br>ity <br><br> CASSA CE SABLE<br><br> SHE A A GUEL<br><br>JOA<br><br>ONCE<br><br>City Councilor<br><br><u>EX-OFFICIO MEMBERS:</u><br><br>1 NCHAI<br><br> (Pr Ide <u>i</u><u> a </u>Mg Barangay)<br><br>City Councilor<br><br>BELL M. ODYOD<br><br>(IPMandat ry Representative)<br><br>City Councilor<br><br>CORRECT:<br><br>CERTIFIED <br><br>CERTIFIED <br><br>ATTE<u>STE</u>D:<br><br>NE<br><br>TILLO TAN<br><br>City Vic r & Presiding Officer<br><br>APPROVED:<br><br>NA or<br><br>ATTY. ALYSSA SH P. TAN, CPA<br><br>City M <br><br>Page 2 of2 pages ofResolution No. 12thCC-051', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-10-06 02:07:16.000000', '2026-10-06 03:04:02.000000', 'bffc5281a9f96e3ee13bf715f92646c6b1b930c40324a1807afdabc478287eaa', 'b4f39005182a0122', 'mayor', '2026-10-06 03:04:02.000000', 0, NULL, 'R12thCC-051 Encouraging all Tourism Related Establishments within the City of Santiago to Establish their own One Town One Product OTOP Kiosks.docx', 592999, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '5fcc7e39a1b0dd28_R12thCC-051_Encouraging_all_Tourism_Related_Establishments_within_the_City_of_Santiago_to_Establish_their_own_One_Town_One_Product_OTOP_Kiosks.docx', NULL, '7486bc1d2df7e69c', 'isu', '2026-10-06 02:07:38.000000', '13de96585e0c7c84ec2461e2891b1133dce62ead5c3f4716b7aa7bf15a0679f4', NULL, NULL, 'Legislative Matters', 'Archived for Local Download', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, 'LCE Approved', '2026-10-06 03:04:02.000000', 'b4f39005182a0122', 'FILE - Local Offline Archive', NULL, NULL, 'Republic of the PhilippinesCity of Santiago-000-OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSODEXCERPT FROM THE MINUTES OF THE REGULAR SESSION OF THE 12TH CITY COUNCIL HELD ON SEPTEMBER 29, 2025 AT AMPHITHEATER, BARANGAY HALL,SAN ANDRES, SANTIAGO CITYAPPROVED UNDER SUSPENDED RULESSponsored by: Coun.Joan Mae V. De JesusCo-sponsored by: Coun. Cassandra Eunice SableCoun. Author: Not stated; Sponsor: Not stated.', 'Archive', NULL, NULL, NULL, NULL, '', 'Secretariat', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, '2026-10-06 03:04:02.000000', NULL, 'LEG-2026-532AC156', '2026-10-06 02:07:16.000000', 'bffc5281a9f96e3ee13bf715f92646c6b1b930c40324a1807afdabc478287eaa', '2026-10-06 03:04:02.000000', NULL),
