INSERT INTO `legislatives` (`id`, `title`, `type`, `status`, `desc`, `content`, `ref`, `createdById`, `createdByName`, `createdByRole`, `createdAt`, `updatedAt`, `documentHash`, `lastModifiedById`, `lastModifiedByName`, `lastModifiedAt`, `published_to_public`, `published_to_public_at`, `file_name`, `file_size`, `file_type`, `file_path`, `sent_to_user_ids`, `sent_by_id`, `sent_by_name`, `sent_at`, `fileRevisionHash`, `fileDiffSummary`, `fileChangeLog`, `intake_classification`, `routing_status`, `stream_type`, `assigned_committee`, `date_referred`, `committee_report_status`, `hearing_date`, `lce_action`, `lce_action_at`, `lce_action_by_id`, `archive_status`, `author_name`, `sponsor_name`, `ai_summary`, `workflow_status`, `admin_decision_notes`, `admin_decision_at`, `document_number`, `registration_date`, `origin`, `originating_office`, `assigned_to_id`, `assigned_to_name`, `assigned_role`, `version_number`, `signed_by_id`, `signed_by_name`, `signed_at`, `signed_document_hash`, `signature_value`, `signature_verified_at`, `verification_token`, `control_number`, `received_at`, `signed_hash`, `locked_at`, `scan_file_path`) VALUES
('99d2ff63c69bc204', 'pogi', 'Bill', 'agenda_created', '', '2.1 Related Literature / Theoretical Background\r\nA. Foreign Related Literature\r\n1. OECD Digital Government Policy Framework\r\nThe \r\nOrganization\r\n for Economic Co-operation and Development (OECD, 2020) presented the Digital Government Policy Framework, which identifies six dimensions of mature digital government: digital by design, data-driven public sector, government as a platform, open by default, user-driven government, and proactive government. The framework emphasizes that digital transformation should not simply convert paper documents into electronic files but should redesign government processes to become more integrated and efficient.\r\nThis literature is relevant to E-Legis because the proposed system does more than store legislative documents digitally. It integrates document routing, agenda preparation, session management, notifications, reporting, and document verification into a single web-based environment.\r\n2. Digital Transformation in Government\r\nThe OECD (2020) explained that digital transformation affects government operations by encouraging the strategic use of digital technologies and data. Government organizations are expected to redesign internal processes, improve coordination, and provide more responsive services rather than merely placing existing services online.\r\nThis supports the development of E-Legis because the system seeks to transform the traditional paper-based legislative workflow into an integrated digital workflow. The system can therefore be viewed as part of the broader movement toward digital government.\r\n3. Electronic Document Management\r\nElectronic document management systems provide organizations with mechanisms for storing, organizing, retrieving, tracking, and distributing digital documents. Such systems are particularly important in organizations where documents must pass through multiple departments and approval stages.\r\nHung et al. found that electronic document management is an important component of e-government because successful implementation depends not only on technical functionality but also on user acceptance, training, compatibility, and facilitating conditions\r\nThis concept directly relates to E-Legis because legislative documents pass through several users, including the Mayor\'s Office, Secretariat, Presiding Officer, and Council Members.\r\n4. Artificial Intelligence in Public Governance\r\nArtificial intelligence has increasingly been applied to government processes to support decision-making, automation, classification, and service delivery. Sousa et al. reviewed AI applications in the public sector and found increasing interest in using AI to improve government services while also identifying ethical and policy considerations.\r\nFor E-Legis, this literature provides support for the use of AI-assisted features such as document classification, summarization, intelligent search, and speech-to-text processing.\r\n5. Artificial Intelligence and Legal Documents\r\nAriai and Demartini (2024) reviewed 127 studies involving natural language processing in the legal domain. Their review identified legal document summarization, legal text classification, named entity recognition, question answering, and legal judgment prediction as important NLP applications. The authors also emphasized challenges associated with the long and complex structure of legal documents.\r\nThis is highly relevant to E-Legis because ordinances, resolutions, minutes, and other legislative documents contain complex legal language. AI-assisted classification and summarization can help legislative personnel locate and understand important information more efficiently.\r\n6. Legal Document Summarization\r\nLegal documents are often lengthy and contain multiple sections, references, and provisions. Recent literature on legal document summarization indicates that NLP can be used to produce shorter versions of legal documents while preserving important information.\r\nGhosh et al. examined extractive and abstractive approaches to legal case-document summarization and noted that legal documents present particular challenges because of their length and specialized language.\r\nThis supports the inclusion of an AI summarization feature in E-Legis, particularly for helping users quickly review lengthy ordinances, resolutions, and session-related documents.\r\n7. Intelligent Legal Information Retrieval\r\nModern legal information systems increasingly use NLP to improve the retrieval of relevant legal provisions. Louis et al. demonstrated that legal information retrieval can be improved by considering the structural relationships between legal provisions rather than treating each document as an isolated text.\r\nThis literature supports E-Legis\'s intelligent search functionality. The system can help users locate relevant legislative records more efficiently than manually searching through physical files.\r\n8. Blockchain and Government\r\nBlockchain technology has been increasingly investigated for government applications because of its potential to improve transparency, security, and trust. A systematic review of blockchain applications in government analyzed 175 scholarly articles and found applications involving public services, electronic voting, registration, transparency, and security.\r\nThis provides theoretical support for the document-verification component of E-Legis. However, the manuscript correctly limits its blockchain-related functionality to SHA-256 hash verification, rather than claiming that the entire system is a distributed blockchain network. Your manuscript specifically states this limitation.\r\n9. Blockchain Adoption Challenges\r\nAlthough blockchain can improve security and transparency, its adoption in government organizations also presents challenges. A systematic review identified interoperability, technical expertise, and organizational factors as important barriers to blockchain adoption in public organizations.\r\nThis supports the decision of E-Legis to use a relatively lightweight hash-verification approach rather than implementing a complex public blockchain infrastructure.\r\n10. Digital Government and User-Centered Services\r\nThe OECD emphasizes that mature digital government should be user-driven and should redesign internal processes around the needs of users. Digital technologies should improve efficiency, accessibility, coordination, and transparency rather than simply replicate paper-based procedures electronically.\r\nThis principle is applicable to E-Legis because different users have different responsibilities. The Secretariat manages documents and agendas, Council Members review legislative materials, and the Presiding Officer performs approval functions.\r\nB. Local Related Literature\r\n1. Republic Act No. 7160 – Local Government Code\r\nRepublic Act No. 7160, or the Local Government Code of 1991, establishes the functions and responsibilities of local government units and their legislative bodies. The Sangguniang Panglungsod is responsible for passing ordinances and resolutions within its jurisdiction. Your manuscript uses this legal framework to establish the importance of legislative document processing in local governance.\r\nThis provides the institutional basis for E-Legis because the system is specifically designed for legislative offices such as the Sangguniang Panglungsod.\r\n2. Republic Act No. 12254 – E-Governance Act\r\nRepublic Act No. 12254 institutionalizes the Philippine government\'s transition toward e-governance. It covers national government agencies as well as local government units and promotes interoperability, digital transformation, data security, transparency, and efficient government processes.\r\nThe law is directly related to E-Legis because the proposed system digitizes internal legislative operations and supports paperless government transactions.\r\n3. Implementing Rules and Regulations of the E-Governance Act\r\nThe 2026 Implementing Rules and Regulations of Republic Act No. 12254 provide additional guidance for implementing e-governance in government organizations. The IRR emphasizes secure, integrated, and digitally enabled government services.\r\nThis strengthens the relevance of E-Legis because the system incorporates digital workflows, electronic records, access controls, and document security.\r\n4. Philippine Development Plan 2023–2028\r\nThe Philippine Development Plan 2023–2028 identifies digital transformation as an important government priority. It specifically promotes paperless, cashless, and data-empowered transactions and calls for the improvement of government processes through digital technologies.\r\nThe direction of the plan supports E-Legis because the system aims to reduce paper dependency and improve the efficiency of legislative processes.\r\n5. Data Privacy Act of 2012\r\nRepublic Act No. 10173, or the Data Privacy Act of 2012, establishes requirements for protecting personal information processed by government and private organizations. It covers the collection, storage, retrieval, modification, and other processing of personal information.\r\nThis is important to E-Legis because the system manages user accounts, attendance, legislative records, and other information that must be protected from unauthorized access.\r\n6. Data Privacy Act Implementing Rules\r\nThe National Privacy Commission\'s implementing rules emphasize security safeguards, documentation, accountability, and appropriate access to personal information.\r\nThese principles support the security requirements of E-Legis, particularly user authentication, authorization, role-based access, and secure handling of legislative records.\r\n7. Philippine Government Digital Transformation\r\nThe Philippine government has increasingly emphasized digital transformation as a means of improving public service delivery. Government policies encourage agencies and LGUs to replace fragmented manual processes with integrated digital systems.\r\nThe Philippine Development Plan identifies digitalization as a mechanism for improving efficiency, transparency, and government service delivery.\r\nThis provides a national policy foundation for the development of E-Legis.\r\n8. Government Digital Document Management\r\nIn 2026, the Department of the Interior and Local Government launched the Document Management System for LGUs (DMS4LGUs). The platform is intended to digitize and centralize government records while reducing paper-based processes and improving document tracking, security, coordination, and transparency.\r\nThe initiative demonstrates that digital document management is becoming an important component of Philippine local governance and closely supports the direction of E-Legis.\r\n9. E-Governance and Local Government Websites\r\nSiar\'s study of Philippine city government websites found that although local governments had increased their web presence, the adoption and utilization of websites as e-governance tools remained limited.\r\nThis literature suggests that simply having a website is insufficient. Government offices need systems that support actual internal workflows, document processing, and administrative functions, which is the gap E-Legis attempts to address.\r\n10. Digital Governance and Philippine LGUs\r\nRecent Philippine policy literature continues to emphasize the need for local government units to improve digital infrastructure, capacity, interoperability, and citizen-oriented services. The current national e-governance framework specifically includes LGUs and back-end government operations.\r\nTherefore, E-Legis is consistent with the country\'s broader movement toward digitally integrated local government operations.\r\n2.2 Related Studies\r\nA. Foreign Related Studies\r\n1. Hung et al. – Electronic Document Management System\r\nHung et al. investigated user acceptance of an electronic document management system in Taiwan. Using 186 users and a Theory of Planned Behavior framework, the study found that perceived usefulness, ease of use, training, compatibility, self-efficacy, and facilitating conditions affected users\' intention to use the system.\r\nThis study is relevant to E-Legis because successful implementation depends not only on developing the system but also on ensuring that legislative personnel can understand and effectively use its functions.\r\n2. Zuiderwijk, Chen, and Salem – AI in Public Governance\r\nZuiderwijk et al. conducted a systematic literature review on AI applications in public governance. Their review identified a growing body of research on AI in government but also emphasized the need for empirical research, ethical considerations, and multidisciplinary approaches.\r\nThe study supports the inclusion of AI in E-Legis while highlighting the importance of responsible implementation and evaluation.\r\n3. Sousa et al. – AI in the Public Sector\r\nSousa et al. reviewed 59 studies involving artificial intelligence in the public sector. Their findings showed increasing use of AI technologies in government services and identified both potential benefits and ethical considerations.\r\nThe findings support the use of AI-assisted document processing in E-Legis but indicate that AI functionality should be treated as decision support rather than an unrestricted replacement for human review.\r\n4. Ghosh et al. – Legal Document Summarization\r\nGhosh et al. compared extractive and abstractive approaches for legal case-document summarization. The study emphasized that legal documents are difficult to summarize because they are lengthy and contain complex information.\r\nThe findings are relevant to the AI summarization component of E-Legis, particularly for reducing the time required to review lengthy legislative documents.\r\n5. Louis et al. – Statutory Article Retrieval\r\nLouis, van Dijck, and Spanakis developed a graph-augmented approach for retrieving relevant statutory articles. Their experiments demonstrated improvements over strong retrieval baselines by incorporating the structural organization of legislation.\r\nThis study supports the intelligent-search functionality proposed for E-Legis because legislative users need to locate relevant ordinances, resolutions, and provisions efficiently.\r\n6. Ma et al. – Legal Case Retrieval\r\nMa et al. developed CaseEncoder, a knowledge-enhanced model for legal case retrieval. The researchers found that general-purpose language models may not adequately capture legal characteristics and therefore proposed legal-specific training methods.\r\nThis is relevant to E-Legis because legislative documents contain specialized terminology and structures. AI features should therefore be designed with consideration for the characteristics of legislative texts.\r\n7. Nguyen et al. – Legal Text Retrieval\r\nNguyen et al. investigated joint learning for legal text retrieval and textual entailment. Their empirical findings showed that combining information about document relevance and legal conclusions can improve legal information retrieval.\r\nThe study supports the development of intelligent legislative search because relevant information may depend on relationships among different sections and documents.\r\n8. Abidin and Munggaran – Blockchain Document Verification\r\nAbidin and Munggaran studied blockchain-based digital document verification using SHA-256. Their work demonstrated the usefulness of cryptographic hashing for verifying document integrity. Your manuscript already identifies this source as part of the technical foundation of the project.\r\nThis directly supports the E-Legis feature that calculates and compares document hashes to detect unauthorized modifications.\r\n9. Blockchain Adoption in Government Organizations\r\nA systematic review of blockchain adoption in government organizations identified 72 factors influencing adoption. The study emphasized that technological, organizational, and environmental factors all affect whether blockchain solutions can successfully be implemented.\r\nThe findings support E-Legis\'s limited implementation of blockchain-inspired verification rather than attempting to deploy a complete distributed blockchain infrastructure.\r\n10. Electronic Records Management in Government\r\nA study of electronic records management implementation in a government land board examined the organizational and human factors affecting adoption. The research used questionnaires, interviews, and document reviews to assess implementation.\r\nThe findings demonstrate that technology alone does not guarantee successful electronic records management. Organizational readiness, user knowledge, and change management are also important considerations for E-Legis.\r\nB. Local Related Studies\r\n1. Cruz and Balahadia – Laguna Legislative Management\r\nCruz and Balahadia (2023) developed a legislative management and tracking system for the Province of Laguna using the Latent Dirichlet Allocation algorithm. The study explored the use of machine learning to identify themes from previous ordinances and resolutions. Your manuscript identifies this study as evidence that AI techniques can be applied to Philippine legislative records.\r\nThe study is highly relevant to E-Legis because both systems use intelligent processing to improve access to legislative documents.\r\n2. Gabuya – Paperless Legislative Sessions\r\nGabuya (2025) examined the readiness of the Sangguniang Bayan of LGU Motiong to transition from paper-based sessions to paperless legislative operations. The study surveyed 13 legislative personnel and considered digital tools, digital literacy, familiarity with paperless platforms, and institutional support.\r\nThis study is directly related to E-Legis because it demonstrates that Philippine legislative offices are actively considering the transition toward digital and paperless sessions.\r\n3. Rodriguez et al. – eDALAYON\r\nRodriguez et al. (2024) developed eDALAYON, a document management and monitoring system for the Department of the Interior and Local Government in the Philippines. The study addressed document management and monitoring within a government setting. Your manuscript cites this research as evidence that manual document management can result in delays, lost routing information, and reduced transparency.\r\nThe study supports E-Legis because both systems focus on improving document monitoring and government workflow.\r\n4. Gamido et al. – Electronic Document Management\r\nGamido, Gamido, and Macaspac (2023) investigated an electronic document management system for LAN-based organizations. The study demonstrates the usefulness of electronic document management for organizing and retrieving organizational records.\r\nThis relates to E-Legis because legislative documents can be centralized in a database and retrieved without depending on physical filing systems.\r\n5. Lagman et al. – Digital Governance Information System\r\nLagman et al. (2025) developed and evaluated an enterprise-level information system for digital governance in Philippine state universities and colleges using Agile methodology and ISO/IEC 25010. The study is relevant to E-Legis because it demonstrates the applicability of Agile development and software-quality evaluation within a Philippine institutional setting.\r\nThe study supports the methodology used by E-Legis, particularly iterative development and software quality assessment.\r\n6. LeMTrac – Legislative Management and Tracking System\r\nThe LeMTrac study developed a legislative management and tracking system for municipal legislative offices in Nabua and Bula, Camarines Sur. The system was evaluated by end-users and IT experts and received a high acceptability rating, particularly for usability. It also improved document accessibility, security, and management.\r\nLeMTrac is one of the most closely related studies to E-Legis because both focus specifically on legislative document management and workflow tracking in Philippine local government.\r\n7. Lagura – Digital Governance Divide in Philippine Cities\r\nLagura (2025) assessed the websites of 33 highly urbanized Philippine cities and identified gaps involving content quality, privacy, inclusivity, public engagement, and technical infrastructure.\r\nThe study indicates that Philippine LGUs have varying levels of digital governance maturity. E-Legis addresses a more specialized need by providing an internal legislative workflow system rather than relying solely on public-facing websites.\r\n8. Dela Peña – E-Governance in Paracale\r\nDela Peña examined e-government services in the Local Government Unit of Paracale, Camarines Norte. The study evaluated functionality, reliability, usability, performance efficiency, compatibility, maintainability, portability, and security using the ISO 25010 standard.\r\nThis study is relevant to E-Legis because the current manuscript also evaluates system quality using ISO/IEC 25010.\r\n9. Valiente – Legislative Records Management System\r\nValiente developed a proposed Legislative Records Management System for the Sangguniang Bayan of Garchitorena. The study identified problems associated with manual \r\nand paper-based records, including delayed retrieval, limited accessibility, risk of record loss, and operational inefficiency.\r\nThis study strongly supports E-Legis because the identified problems are similar to those stated in the E-Legis project context.\r\n10. Legislative Management and E-Session System for Motiong\r\nA 2026 study developed a Legislative Management and E-Session System for the Sangguniang Bayan of LGU Motiong, Samar. The proposed web-based system integrates legislative management and electronic session functions to address delays, document-management difficulties, and problems associated with paper-based processes.\r\nThis study is particularly relevant to E-Legis because it demonstrates the growing development of web-based legislative and e-session systems in Philippine local government.\r\nReference:\r\n Abidin, M. F., & Munggaran, L. C. (2025). \r\nBlockchain-based digital document verification using SHA-256 on the Internet Computer Protocol (ICP).\r\n \r\n Ariai, F., & Demartini, G. (2024). \r\nNatural language processing for the legal domain: A survey of tasks, datasets, models, and challenges.\r\n \r\n  Cruz, C. A., & Balahadia, F. F. (2023). \r\nProvince of Laguna legislative management and tracking system with the application of Latent Dirichlet Allocation (LDA) algorithm.\r\n \r\nGabuya, R. J. B. (2025). \r\nTowards digital legislation: Readiness of the Sangguniang Bayan of LGU Motiong for paperless sessions.\r\n \r\n Gamido, M. V., Gamido, H. V., & Macaspac, D. J. P. (2023). \r\nElectronic document management system for local area network-based organizations.\r\n \r\n Ghosh, K., Goyal, P., & Ghosh, S. (2022). \r\nLegal case document summarization: Extractive and abstractive methods and their evaluation.\r\n \r\n Lagman, A. C., et al. (2025). \r\nDevelopment and evaluation of an enterprise-level information system for digital governance in Philippine SUCs using agile software methodology and ISO/IEC 25010 software quality model.\r\n \r\nOECD. (2020). \r\nThe OECD Digital Government Policy Framework: Six dimensions of a digital government.\r\n \r\n Republic Act No. 10173. (2012). \r\nData Privacy Act of 2012.\r\n \r\nRepublic Act No. 12254. (2025). \r\nE-Governance Act.\r\n \r\nRodriguez, B., III, et al. (2024). \r\neDALAYON: A document management and monitoring system for the Department of the Interior and Local Government, Philippines.\r\n \r\nSiar, S. V. (2007). \r\nE-governance at the local government level in the Philippines: An assessment of city government websites.\r\n \r\nSousa, W. G., et al. (2019). \r\nHow and where is artificial intelligence in the public sector going? A literature review and research agenda.\r\n \r\nValiente, S. M. N. (2026). \r\nDesign of a Legislative Records Management System: A phased intervention for the Sangguniang Bayan of Garchitorena.\r\n \r\nZuiderwijk, A., Chen, Y.-C., & Salem, F. (2021). \r\nImplications of the use of artificial intelligence in public governance: A systematic literature review and a research agenda.', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-09-22 22:03:26.000000', '2026-09-27 00:25:07.000000', '9b08cbbe5fa46822f20497ab7de8ca7c77f6dc7725b2f3810ddda543df9cd89d', 'c59939d58ad69391', 'pogi', '2026-09-27 00:25:07.000000', 0, NULL, 'rrlrrs.docx', 24246, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '1781889b6c929828_rrlrrs.docx', NULL, '7486bc1d2df7e69c', 'isu', '2026-09-27 00:04:36.000000', '083145b9770abcf4a6b2accf9218324e6b2105772a8f19e71dfc437369a8a125', NULL, '[{\"changed_at\":\"2026-09-22T22:04:20+08:00\",\"changed_by_id\":\"7486bc1d2df7e69c\",\"changed_by_name\":\"isu\",\"change_reason\":\"Updated file content\",\"summary\":\"Saved file content\",\"diffSummary\":null}]', 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SP Session', NULL, NULL, 'LEG-2026-99D2FF63C69B', '2026-09-22 22:03:26.000000', 'isu', 'council members', NULL, 'Council Members', 'council members', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-99D2FF63', '2026-09-22 22:03:26.000000', NULL, NULL, NULL),
('a0f998cc62beda08', 'SP Sec Flowchart (1)', 'Bill', 'draft', '', '<p></p>', '', 'c59939d58ad69391', 'pogi', 'admin', '2026-09-23 02:08:40.000000', '2026-09-25 01:02:38.000000', 'd6cbe96288b8d827f3786354138f4fc89b7a84657a003f9f463244adcd103d50', 'c59939d58ad69391', 'pogi', '2026-09-25 01:02:38.000000', 0, NULL, 'SP Sec Flowchart (1).docx', 447814, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '40065904eda3fb0b_SP_Sec_Flowchart__1_.docx', NULL, NULL, NULL, NULL, '9ab82aeba2008b266b7dadef2cda3ccea650153140c47950620fd8b026af256b', NULL, NULL, 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', 'Approval', NULL, NULL, 'LEG-2026-A0F998CC62BE', '2026-09-23 02:08:40.000000', 'pogi', 'admin', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-A0F998CC', '2026-09-23 02:08:40.000000', NULL, NULL, NULL),
('aeb51774340d55bd', 'sdjfwe', 'Bill', 'agenda_created', '', '', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-09-13 23:31:18.000000', '2026-09-13 23:31:55.000000', '14dc9df36127ee442597ea0a081ffe819f48b104d7a0039d5a91573872c2701d', 'c59939d58ad69391', 'pogi', '2026-09-13 23:31:55.000000', 0, NULL, 'E-Legis System chapter1_3 (1).pdf', 441484, 'application/pdf', 'ee375a83a2f8cac4_E-Legis_System_chapter1_3__1_.pdf', NULL, '7486bc1d2df7e69c', 'isu', '2026-09-13 23:31:24.000000', 'b08fb12661676ae5042471ef256f7a1d316bd6ddeffd5cff2a70616cb1981d27', NULL, NULL, 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Receiving', NULL, NULL, 'LEG-2026-AEB51774340D', '2026-09-13 23:31:18.000000', 'isu', 'council members', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-AEB51774', '2026-09-13 23:31:18.000000', NULL, NULL, NULL),
('ef6aaa6cf04a5c32', 'Republic of the Philippines City of Santiago -000-', 'Bill', 'draft', '', '<p>Republic of the Philippines City of Santiago -000-</p><p>OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSOD</p><p>EXCERPT FROM THE MINUTES OF THE 4TH REGULAR SESSION</p><p>OF THE 12TH CITY COUNCIL HELD ON AUGUST 1 1, 2025 AT SP SESSION HALL,</p><p>2ND FLOOR, CITY HALL, SAN ANDRES, SANTIAGO CITY</p><p>APPROVED UNDER SUSPENDED RULES</p><p></p><p>Sponsored by: Coun. Cassandra Eunice Sable</p><p>Co-sponsored by: Coun. Tomirose Bautista-dela Cruz Coun. Sherman A. Miguel</p><p>Coun. Anton Phoenix A. Abaya</p><p>Coun. Joan Mae V. de Jesus</p><p>Coun. Jay Arcie S. Co</p><p>Coun.Russel D. Ponce</p><p>Coun. Carlo N. de Luna</p><p>Coun.Orlando T. Chan</p><p>Coun. Benzi Tan Chai</p><p>Coun. Christopher G. Respicio</p><p>Coun. Bella M. Yodyod</p><p></p><h1>RESOLUTION NO. 12THCC-023</h1><p>AUTHORIZING THE HONORABLE CITY MAYOR, ATTY. ALYSSA SHEENA P. TAN, CPA, FOR AND ON BEHALF OF THE CITY GOVERNMENT OF SANTIAGO, TO ENTER INTO AND SIGN THE MEMORANDUM OF AGREEMENT (MOA) WITH THE COMMISSION ON POPULATION AND DEVELOPMENT REGION 11,</p><p>RELATIVE TO THE UTILIZATION OF THE 2025 RAFAEL M. SALAS KAUNLARANG PANTAO AWARD (RMSKPA) CASH GRANT</p><p>WHEREAS, the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) is a recognition and award program for institutions and individuals who have significantly contributed to the advancement of the Population and Development Agenda. With the devolution policy, the role of Local Government Units (LGUs) has been more pronounced in advancing the Philippine Population and Development Plan of Action specially in institutionalizing and localizing Population Development (POPDEV) strategies;</p><p>WHEREAS, the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) is a prestigious recognition that honors the Most Outstanding LGUs in the country for their exemplary efforts in mainstreaming and localizing the Population and Development Agenda within their local governance systems;</p><p>WHEREAS, the Philippine Population and Development Plan of Action (PPD-POA) 2023-2028 serves as the overall blueprint for inter-agency population challenges in order to accelerate the attainment of the Administration&#039;s socio-economic development agenda under PDP 2023-2028;</p><p>WHEREAS, by virtue of a Presidential and Cabinet Directive issued in 2019, the Commission on Population and Development (CPD) is directed to coordinate with relevant government agencies and LGUs for the intensified implementation of the Philippine Population and Development Program (PPDP) at all levels;</p><p>WHEREAS, the Local Government Unit of Santiago City has been adjudged as the Regional Winner of the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) — Search for the Most Outstanding LGUs in Localizing the Population and Development (POPDEV) Agenda (city category), thereby qualifying to receive a cash grant amounting to Fifty Thousand Pesos (P50,OOO.OO)•,</p><p>Page I of2 pages ofResolution No. 12thCC-02 l!åj</p><p>WHEREAS, a Memorandum of Agreement (MOA) between the City Government of Santiago and the Commission on Population and Development Region Il aims to improve the policy and program implementation at the local level and ensure localization and institutionalization of population-related strategies and interventions;</p><p>WHEREAS, under Section 8 paragraph (b) (1) (f) of Republic Act No. 7720, the City Mayor shall represent the City in all its business transactions and sign on its behalf all bonds, contracts, and obligations, and such other documents upon authority of the Sangguniang Panlungsod or under existing laws or ordinances;</p><p>WHEREFORE, on motion of Coun. Cassandra Eunice Sable, unanimously seconded, be it</p><p>RESOLVED, as it is hereby resolved, to authorize Honorable City Mayor, Atty. Alyssa Sheena P. Tan, CPA, for and on behalf of the City Government of Santiago, to enter into and sign the Memorandum of Agreement (MOA) with the Commission on Population and Development Region Il, relative to the utilization of the 2025 Rafael M. Salas Kaunlarang Pantao Award (RMSKPA) Cash Grant.</p><p>RESOLVED FURTHER, to furnish copies of this Resolution to all persons, offices, and government agencies concerned for their information and guidance.</p><p>ADOPTED. AUGUST 11, 2025.</p><p>CERTIFIED TRUE AND CORRECT:</p><p>MARY M A H. VELASCO or-s r t o the Sanggunian</p><p>ATTESTED:</p><p>A </p><p></p><p>	JAMAYNE 	LO TAN</p><p>	City Vice Mayor	residing Officer</p><p>APPROVED:</p><h1>ATTY. ALYSSA SHE NA P. TAN, CPA</h1><p>City M r</p><p>Page 2 of2 pages ofResolution No. 12thCC-023</p>', '', '7486bc1d2df7e69c', 'isu', 'council members', '2026-10-06 01:24:53.000000', NULL, '7c782601d93e969d60ec7d129f96352d944d078bae93717820791580d9b35c0a', NULL, NULL, NULL, 0, NULL, 'R12thCC-023 MOA with the Commission on Population and Development Region II Relative to the Utilization of the 2025 Rafael M. Salas Kaunlarang Pantao Award RMSKPA Cash Grant.docx', 127525, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', '1950ee3451f1020f_R12thCC-023_MOA_with_the_Commission_on_Population_and_Development_Region_II_Relative_to_the_Utilization_of_the_2025_Rafael_M._Salas_Kaunlarang_Pantao_Award_RMSKPA_Cash_Grant.docx', NULL, NULL, NULL, NULL, '036673338c5aca187cffb00488efbd9e34885fa454c714f6bfc31299b8db7f82', NULL, NULL, 'Legislative Matters', 'For Agenda', 'Approved Resolutions/Ordinances', NULL, NULL, 'Pending', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Republic of the Philippines City of Santiago -000-OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSODEXCERPT FROM THE MINUTES OF THE 4TH REGULAR SESSIONOF THE 12TH CITY COUNCIL HELD ON AUGUST 1 1, 2025 AT SP SESSION HALL,2ND FLOOR, CITY HALL, SAN ANDRES, SANTIAGO CITYAPPROVED UNDER SUSPENDED RULESSponsored by: Coun. Cassandra Eunice SableCo-sponsored by: Coun. Tomirose Bautista-dela Cruz Coun. Author: Not stated; Sponsor: Not stated.', 'Receiving', NULL, NULL, NULL, NULL, '', 'Secretariat', NULL, NULL, 'Secretariat', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'LEG-2026-EF6AAA6C', '2026-10-06 01:24:53.000000', NULL, NULL, NULL);

