('0c30d3054a2744c0', '0d5eb969c1aa3b95', 1, 'pogi', '', 'O11thCC-004-Mandating-all-Water-Refilling-Stations-and-Food-Establishments-within-the-City-of-Santiago-to-Have-their-Potable-Water-Undergo-Bacteriological-Test-Once-a-Month.pdf', '311e3ecc2613cd8f_O11thCC-004-Mandating-all-Water-Refilling-Stations-and-Food-Establishments-within-the-City-of-Santiago-to-Have-their-Potable-Water-Undergo-Bacteriological-Test-Once-a-Month.pdf', '10e7fe40c0822692d8da4c51ed1922abe8d7652541cff6a0ddc68b5a64923d46', '7486bc1d2df7e69c', 'isu', '2026-09-22 21:57:25.000000', 'Baseline snapshot migrated from existing record', NULL, '0d5eb969c1aa3b95', 'Signed v1'),
('199ff74e5f48bf27', '', 1, 'Republic of the Philippines', '<p>Republic of the Philippines</p><p>City of Santiago</p><h1>-000-</h1><p>OFFICE OF THE SECRETARY - SANGGUNIANG PANLUNGSOD</p><p>EXCERPT FROM THE MINUTES OF THE 	REGULAR SESSION OF THE 12TH CITY COUNCIL HELD ON SEPTEMBER 29, 2025 AT AMPHITHEATER, BARANGAY HALL,</p><p>SAN ANDRES, SANTIAGO CITY</p><p>APPROVED UNDER SUSPENDED RULES</p><p></p><p>Sponsored by: Coun.Joan Mae V. De Jesus</p><p>Co-sponsored by: Coun. Cassandra Eunice Sable</p><p>Coun. Tomirose Bautista-Dela Cruz</p><p>Coun. Sherman A. Miguel</p><p>Coun. Anton Phoenix A. Abaya</p><p>Coun.Jay Arcie S. Co</p><p>Coun. Russel D. Ponce</p><p>Coun. Gino Antonio A. Siquian</p><p>Coun. Carlo N. De Luna</p><p>Coun. Orlando T. Chan</p><p>Coun. Benzi Tan Chai</p><p>Coun. Christopher G. Respicio Coun. Bella M. Yodyod</p><p></p><h2>RESOLUTION NO. 12THCC-051</h2><p>A RESOLUTION ENCOURAGING ALL TOURISM-RELATED ESTABLISHMENTS WITHIN THE CITY OF SANTIAGO TO ESTABLISH THEIR OWN ONE TOWN, ONE PRODUCT (OTOP) KIOSKS</p><p>WHEREAS, Republic Act No. 11960, otherwise known as the &quot;OTOP Philippines Act, institutionalizes the One Town, One Product Program as a national strategy to promote inclusive local economic development, support micro, small, and medium enterprises (MSMEs), and preserve cultural heritage through the advancement of community-based products and services;</p><p>WHEREAS, the Department of Trade and Industry (DTI), in partnership with local government units (LGUs), has established OTOP Hubs to serve as centralized venues for the marketing, distribution, and promotion of locally crafted goods, processed food items, and skill-based services, among others;</p><p>WHEREAS, tourism-related establishments—including but not limited to hotels, resorts, restaurants, travel agencies, and pasalubong centers—are strategically positioned to serve as platforms for showcasing the City of Santiago&#039;s unique local products to both domestic and international visitors;</p><p>WHEREAS, the integration of OTOP kiosks within such establishments is expected to enhance product visibility, foster cultural pride, and stimulate economic activity by providing local artisans and entrepreneurs with direct access to consumer markets;</p><p>WHEREAS, to uphold the integrity and objectives of the OTOP Philippines Program, all products to be displayed and sold in said kiosks shall be sourced exclusively from the officially designated OTOP Hub of the City, and must be supplied by duly accredited MSMEs operating within the locality;</p><p>WHEREFORE, on motion of Coun. Joan Mae V. De Jesus, unanimously seconded, be it —</p><p>RESOLVED, as it is hereby resolved, to encourage all tourism-related establishments operating within the territorial jurisdiction of the City of Santiago to establish their own One Town</p><p>One Product (OTOP) kiosks, in support of ocal e rprise development a d cultural promotion;</p><p>on No. 12t</p><p>RESOLVED FURTHER, that products to be displayed and sold in said kiosks shall be sourced from the officially designated OTOP Hub of the City, thereby ensuring quality, authenticity, and alignment with the standards and objectives of the OTOP Philippines Program;</p><p>RESOLVED FINALLY, that copies of this Resolution be furnished to the Department of Trade and Industry, the Santiago City Information, Culture and the Arts, and Tourism Office (CICATO), and all concerned tourism-related establishments for their information, guidance, and appropriate action.</p><p>ADOPTED. SEPTEMBER 29, 2025.</p><p>JESUS</p><p>RUSSE</p><p>CARL </p><p>LUNA</p><p>JESUS</p><p>RUSSE</p><p>CARL </p><p>LUNA</p><p>TOMIROSE </p><p>CRUZ</p><p>ABAYA</p><p>SIQUIAN</p><p>RESPICIO</p><p>ity </p><p>TOMIROSE </p><p>CRUZ</p><p>ABAYA</p><p>SIQUIAN</p><p>RESPICIO</p><p>ity </p><p>	CASSA	CE SABLE</p><p>	SHE A A	GUEL</p><p>JOA</p><p>ONCE</p><p>City Councilor</p><p><u>EX-OFFICIO MEMBERS:</u></p><p>1 NCHAI</p><p>	(Pr Ide	<u>i</u><u> a </u>Mg Barangay)</p><p>City Councilor</p><h2>BELL M. ODYOD</h2><p>(IPMandat ry Representative)</p><p>City Councilor</p><p>CORRECT:</p><p>CERTIFIED </p><p>CERTIFIED </p><p></p><p>ATTE<u>STE</u>D:</p><p></p><p>NE</p><p></p><p>TILLO TAN</p><p>City Vic	r &amp; Presiding Officer</p><p>APPROVED:</p><p></p><p></p><p>NA or</p><h2>ATTY. ALYSSA SH P. TAN, CPA</h2><p>City M </p><p>Page 2 of2 pages ofResolution No. 12thCC-051</p>', 'R12thCC-051 Encouraging all Tourism Related Establishments within the City of Santiago to Establish their own One Town One Product OTOP Kiosks.docx', 'revision_532ac15691dedc0c_v1_5fcc7e39a1b0dd28_R12thCC-051_Encouraging_all_Tourism_Related_Establishments_within_the_City_of_Santiago_to_Establish_their_own_One_Town_One_Product_OTOP_Kiosks.docx', '3527bca630aa351e6f5c1aa5f757368abacf3d10098335a9f49af06ef3b84af1', '7486bc1d2df7e69c', 'isu', '2026-10-06 02:07:16.000000', NULL, NULL, '532ac15691dedc0c', 'Draft v1');
INSERT INTO `legislative_versions` (`id`, `legislative_id`, `version_number`, `title`, `content`, `file_name`, `file_path`, `document_hash`, `created_by_id`, `created_by_name`, `created_at`, `change_reason`, `signed_file_path`, `document_id`, `status`) VALUES
('1b068632cc3ea20f', '', 4, 'Jan Emmanuel R. Guingab_20250124_184325_0000.pdf', '<p><strong>E-LEGIS SYSTEM: ELECTRONIC</strong></p><p><strong>LEGISLATIVE WORKFLOW AND</strong></p><p><strong>DOCUMENT MANAGEMENT</strong></p><p></p><p>A Capstone Project</p><p>Presented to the Faculty Members of the</p><p>College of Information Technology</p><p>Northeastern College</p><p>Santiago City, Isabela</p><p></p><p>In Partial Fulfillment of the</p><p>Academic Requirements for the</p><p>Bachelor of Science in Information Technology (BSIT)</p><p></p><p>By:</p><p>Jan Emmanuel R. Guingab</p><p>Rhestly B. Manuel</p><p>Jude Mark S. Meligrito</p><p>Mark Roland M. Abarro</p><p>Janoah Adriel C. Utanes</p><p>September 2026</p><h1>APPROVAL SHEET</h1><p>The capstone project entitled “E-LEGIS SYSTEM: ELECTRONIC LEGISLATIVE WORKFLOW AND DOCUMENT MANAGEMENT,” prepared and submitted by the researchers in partial fulfillment of the requirements for the degree of BACHELOR OF SCIENCE IN INFORMATION TECHNOLOGY, is hereby endorsed.</p><p><strong>LOIDA F. HERMOSURA, CpE, MSIT</strong></p><p>Adviser</p><p><strong>MARY MAGDALENA H. VELASCO</strong></p><p>Respondent</p><p><strong>MARLON L. CASTRO</strong></p><p>Instructor</p><p></p><p>APPROVED by the Panel on Oral Examination with a grade of PASSED.</p><p><strong>FRANCISCO C. EUGENIO JR., DIT</strong></p><p>Member</p><p><strong>SHERYL JOY M. RASPADO, MIT</strong></p><p>Member</p><p><strong>DARIOS B. ALADO, DIT</strong></p><p>Chairman</p><p></p><p>ACCEPTED AND APPROVED in partial fulfillment of the requirements for the degree of Bachelor of Science in Information Technology.</p><p><strong>LOIDA F. HERMOSURA, CpE, MSIT</strong></p><p>Dean, College of Information Technology</p><p>&lt;br&gt;</p><h1>DEDICATION</h1><p>This capstone project, &quot;E-Legis System: Electronic Legislative Workflow and Document Management,&quot; is dedicated first and foremost to the Almighty God, who granted us the wisdom and strength to complete this work. Without His mercy and blessings, this would never have been possible. We also dedicate this work to our beloved families and parents, for their unconditional love, patience, sacrifices, and constant support throughout this journey.</p><p>&lt;br&gt;</p><h1>ACKNOWLEDGEMENT</h1><p>The researchers wish to express their heartfelt gratitude to the people who made the completion of this capstone project possible.</p><p>First and foremost, to the Almighty God, for the guidance, strength, and wisdom He provided throughout this project.</p><p>To Mrs. Loida F. Hermosura, CpE, MSIT, Dean of the College of Information Technology and the researchers’ capstone adviser, for her patient guidance, constructive corrections, and encouragement from the proposal stage to the final defense.</p><p>To Mr. Marlon L. Castro, capstone instructor, for his detailed comments on the manuscript and for keeping the researchers on track with the required format and schedule.</p><p>To the members of the Panel on Oral Examination, Dr. Darios B. Alado, DIT (Chairman), Dr. Francisco C. Eugenio Jr., DIT, and Ms. Sheryl Joy M. Raspado, MIT, for their valuable suggestions that helped improve the system and this paper.</p><p>To Ms. Mary Magdalena H. Velasco, OIC–Secretary to the Sanggunian and the researchers’ respondent, for accommodating the interviews, sharing the office’s workflow and documents, and supporting the evaluation of the system.</p><p>To the staff of the Sangguniang Panlungsod Secretariat and the council members of Santiago City, who served as respondents and evaluators and generously gave their time and honest feedback.</p><p>Finally, to the researchers’ families, friends, and classmates, for their love, understanding, and constant encouragement throughout this journey.</p><p>&lt;br&gt;</p><h1>ABSTRACT</h1><p>Many local legislative offices in the Philippines still use paper-based processes for ordinance processing, agenda preparation, resolution issuance, attendance tracking, and session management. This practice leads to delayed approvals, duplicated or misplaced documents, difficulty in tracking document status, and inconsistent communication between offices.</p><p>This capstone project developed E-Legis, a web-based legislative workflow and document management system for the Sangguniang Panlungsod of Santiago City, Isabela. E-Legis digitizes document management, automates approval routing, supports session scheduling, attendance monitoring, and electronic voting, and provides AI-supported document processing and a secure document signing and integrity module based on Public Key Infrastructure (PKI) digital signatures, SHA-256 hashing, and QR code verification.</p><p>Through E-Legis, the Sangguniang Panlungsod Secretariat manages agendas, tracks workflows, schedules sessions, publishes ordinances, and generates reports. Council members and the Presiding Officer review agendas, vote, record attendance, and access documents through a tablet-based interface during sessions, while offices such as the Mayor’s Office submit documents and monitor their status online. The AI features include an AI Draft Assistant, document classification, summarization, speech-to-text transcription, and smart search. When an authorized signer signs a finalized document, the system computes its SHA-256 hash, creates a PKI digital signature with the signer’s private key, adds a visible signature block and a QR verification code to the PDF, stores the hash and signature records in MySQL, and locks the signed version. Scanning the QR code confirms who signed the document and whether it has been modified since signing, without the use of a blockchain or any transaction fees.</p><p>The researchers followed the Agile software development methodology, improving system features through iterative development and testing. The system was evaluated by its respondents using the ISO/IEC 25010 software quality model for functional suitability, performance efficiency, compatibility, usability, reliability, security, and maintainability, and obtained an overall weighted mean of 4.42, interpreted as Strongly Agree (Excellent). Load and performance testing recorded a success rate of 100, a throughput of 100, an average response score of 97, and a score of 91 for the SP Secretariat. These scores show that E-Legis loads quickly, handles requests reliably, and supports efficient legislative document management.</p><p>Based on these findings, the researchers concluded that E-Legis is acceptable for use in managing the legislative workflow of the Sangguniang Panlungsod of Santiago City.</p><p>&lt;br&gt;</p><h1>TABLE OF CONTENTS</h1><p>APPROVAL SHEET	ii</p><p>DEDICATION	iii</p><p>ACKNOWLEDGEMENT	iv</p><p>ABSTRACT	vi</p><p>TABLE OF CONTENTS	vii</p><p>LIST OF FIGURES	x</p><p>LIST OF TABLES	xii</p><p><strong>CHAPTER I INTRODUCTION</strong>	1</p><p>1.1 Project Context	1</p><p>1.2 Purpose and Description	4</p><p>1.3 Objectives of the Study	7</p><p>1.4 Scope and Limitation of the Study	10</p><p><strong>CHAPTER II REVIEW OF RELATED LITERATURE AND STUDIES</strong>	13</p><p>2.1 Related Literature/ Theoretical Background	13</p><p>2.1.1 Foreign Related	13</p><p>2.1.2 Local Related	18</p><p>2.2 Related Studies	23</p><p>2.2.1 Foreign Related	23</p><p>2.2.2 Local Related	27</p><p>Synthesis	32</p><p><strong>CHAPTER III TECHNICAL BACKGROUND</strong>	34</p><p>3.1 Technicality of the Project	34</p><p>3.2 Details of Technology to be Used	36</p><p>3.3 How the Project will Work	38</p><p><strong>CHAPTER IV METHODOLOGY</strong>	42</p><p>4.1 Software Development Methodology	42</p><p>4.2 Environment	44</p><p>4.2.1 Locale of the Study	44</p><p>4.2.2 Population of the Study	44</p><p>4.2.3 Organizational Chart and Profile	46</p><p>4.3 Requirement Specification	50</p><p>4.3.1 Operational Feasibility	52</p><p>4.3.2 Technical Feasibility	54</p><p>4.3.3 Schedule Feasibility	56</p><p>4.3.4 Economic Feasibility	56</p><p>4.3.5 Requirements Modeling	59</p><p>4.3.6 Object Modeling	61</p><p>4.4 Design	62</p><p>4.4.1 Output and User-Interface Design	62</p><p>4.4.2 Data Design	71</p><p>4.4.3 System Architecture	74</p><p>4.5 Development	76</p><p>4.5.1 Software Specification	76</p><p>4.5.2 Hardware Specification	77</p><p>4.5.3 Program Specification	78</p><p>4.5.4 Programming Environment	79</p><p>4.5.5 Deployment Diagram	80</p><p>4.6 Development Testing	81</p><p>4.6.1 Evaluation of the AI-Supported Features	81</p><p>4.6.2 Data Gathering Procedure	82</p><p>4.6.3 Data Analysis	83</p><p>4.7 Testing	84</p><p>4.7.1 Unit Testing	84</p><p>4.7.2 Integration Testing	84</p><p>4.7.3 Performance Testing	85</p><p>4.7.4 Load Testing	86</p><p>4.8 Summary of the ISO/IEC 25010 Software Quality Evaluation	86</p><p><strong>CHAPTER V RESULT AND DISCUSSION</strong>	88</p><p>5.1 The Developed System	88</p><p>5.2 System Quality Evaluation Result	89</p><p>5.3 Load and Performance Test Result	91</p><p>5.3.1 Load Test Result	91</p><p>5.3.2 Performance Test Result	91</p><p>5.4 AI-Supported Features Evaluation Result	91</p><p><strong>CHAPTER VI CONCLUSION AND RECOMMENDATION</strong>	94</p><p>6.1 Conclusion	94</p><p>6.2 Recommendations	95</p><p><strong>BIBLIOGRAPHY</strong>	97</p><p><strong>GLOSSARY</strong>	105</p><p>&lt;br&gt;</p><h1>LIST OF FIGURES</h1><p>Figure 1: Technicality Framework of E-Legis	34</p><p>Figure 2: PKI Digital Signing and Verification Workflow of E-Legis	40</p><p>Figure 3: Agile Methodology Framework	42</p><p>Figure 4: Satellite View of the Locale of the Study	44</p><p>Figure 5: Organizational Chart of the Office of the Secretary to the City Council	46</p><p>Figure 6: Current Workflow of the Sangguniang Panlungsod	48</p><p>Figure 7: Fishbone Diagram of the Current Legislative Process	52</p><p>Figure 8: Functional Decomposition Diagram of E-Legis	53</p><p>Figure 9: Gantt Chart of the Project	56</p><p>Figure 10: Context Diagram of E-Legis	59</p><p>Figure 11: Level 1 Data Flow Diagram of E-Legis	60</p><p>Figure 12: Use Case Diagram of E-Legis	61</p><p>Figure 13: Login Page of E-Legis	62</p><p>Figure 14: Dashboard of E-Legis	63</p><p>Figure 15: Analytics and Reports Page	64</p><p>Figure 16: Create Bill Form	65</p><p>Figure 17: Pending Bills and Resolutions Page	65</p><p>Figure 18: Legislative Audit Trail Page	66</p><p>Figure 19: Manage Users Page	67</p><p>Figure 20: Tablet Session Control Panel	67</p><p>Figure 21: Session Scheduling Page	68</p><p>Figure 22: Voice-to-Text Module	69</p><p>Figure 23: Sample Report – My Legislative History	70</p><p>Figure 24: Sample Visible Signature Block with QR Verification Code	70</p><p>Figure 25: Entity Relationship Diagram of E-Legis	71</p><p>Figure 26: Deployment Diagram of E-Legis	80</p><p>Figure 27: Weighted Mean of Each ISO/IEC 25010 Quality Characteristic	90</p><p>Figure 28: Voice-to-Text Transcription Panel	92</p><p>Figure 29: AI Draft Helper Panel	92</p><p>&lt;br&gt;</p><h1>LIST OF TABLES</h1><p>Table 1: Distribution of Respondents	45</p><p>Table 2: User Types and Purpose	45</p><p>Table 3: Document Signing Permissions by User Type	45</p><p>Table 4: Compatibility Checking of Hardware and Software	54</p><p>Table 5: Cost and Benefit Analysis	57</p><p>Table 6: Data Dictionary of kaya_portal_users	72</p><p>Table 7: Data Dictionary of kaya_portal_sessions	72</p><p>Table 8: Data Dictionary of kaya_portal_signer_certificates	72</p><p>Table 9: Data Dictionary of kaya_portal_document_versions	73</p><p>Table 10: Data Dictionary of kaya_portal_document_signatures	73</p><p>Table 11: Hardware Specification	77</p><p>Table 12: Five-Point Likert Scale and Interpretation	83</p><p>Table 13: Summary of the ISO/IEC 25010 Quality Characteristics Evaluated	86</p><p>Table 14: Summary of the ISO/IEC 25010 Evaluation Results	89</p><h1>CHAPTER I</h1><p><strong>INTRODUCTION</strong></p><h2>1.1 Project Context</h2><p>In the Philippines, local legislative councils play an important role in governance by enacting ordinances, resolutions, and programs that affect constituents&#039; welfare. The Sangguniang Panlungsod is the local legislative body of a city, empowered by the Local Government Code of 1991 to enact ordinances and approve resolutions (Republic Act No. 7160, 1991). To do so, the legislative office must handle every document through a cycle of drafting, deliberation, committee referral, approval, and archiving.</p><p>Despite this important function, many local legislative offices still rely on paper-based processes. Cruz and Balahadia (2023) observed that as a legislature produces more documents, manual handling becomes more time-consuming for staff and makes it harder for the public to track legislative records. A 2025 readiness assessment of a Sangguniang Bayan found that although members had the necessary devices and basic digital literacy, the office still depended on printed documents, bore recurring printing costs, and experienced delayed approvals and lost documents (Gabuya, 2025). Other Philippine studies also report that manual document management delays document retrieval, loses routing information, and limits transparency in public offices (Rodriguez et al., 2024; Gamido et al., 2023).</p><p>These conditions run contrary to national policy. Republic Act No. 12254, or the E-Governance Act (2025), commits the government, including local government units, to secure and interoperable digital services. This policy direction shows that digitalizing local legislative processes is not only desirable but increasingly required.</p><p>Beyond digital routing and storage, studies on natural language processing (NLP) show that automatic classification, summarization, and retrieval can help users search long legal texts, highlight key provisions, and find related statutes (Ariai &amp; Demartini, 2024). In the Philippines, Cruz and Balahadia (2023) applied topic modeling to the ordinances and resolutions of the Sangguniang Panlalawigan of Laguna, showing that machine learning can identify themes in legislative records.</p><p>For document integrity, cryptographic hashing offers a practical way to verify that an official document has not been altered. By computing a document’s SHA-256 hash and comparing it with the stored hash, a system can detect even a one-character change in its content (Abidin &amp; Munggaran, 2025). This is valuable for ordinances and resolutions, where authenticity is critical. Hashing alone, however, shows only that a document has changed; it does not prove who approved it. Public Key Infrastructure (PKI) digital signatures address this gap: the signer signs the document’s hash with a private key that only the signer holds, and anyone with the signer’s public key certificate can confirm both the identity of the signer and the integrity of the document (National Institute of Standards and Technology, 2023). In the Philippines, the Electronic Commerce Act of 2000 gives legal recognition to electronic signatures (Republic Act No. 8792, 2000), and Executive Order No. 810 (2009) directs government agencies to apply digital signatures in their e-government services.</p><p>Existing Philippine legislative and document systems address only parts of the problem. LeMTrac (Pandes et al., 2018) and the records management system proposed for Garchitorena (Valiente, 2026) focus on tracking and retrieving legislative records; eDALAYON (Rodriguez et al., 2024) manages general government documents; and the Laguna system (Cruz &amp; Balahadia, 2023) applies topic modeling but does not manage sessions or approvals. None of these systems combine, in one platform for a city legislative office, (a) automated approval routing, (b) session management with attendance and electronic voting, (c) AI-assisted drafting, summarization, and search, and (d) PKI-based digital signing and tamper detection of finalized documents through hashing and QR code verification.</p><p>To address this gap, the researchers developed E-Legis (Electronic Legislative System), an integrated web-based system for the Sangguniang Panlungsod of Santiago City, Isabela. Each feature responds to a problem identified above: digital workflow routing addresses delayed approvals and lost routing information; session management replaces printed agendas and manual attendance and vote counting; AI-supported processing reduces the effort of drafting and searching legislative documents; and PKI digital signatures, combined with SHA-256 hashing and QR code verification, replace manual wet signatures while proving who signed each approved ordinance or resolution and that it has not been changed since it was signed.</p><p>E-Legis also supports the United Nations Sustainable Development Goals (SDGs) under the 2030 Agenda for Sustainable Development (United Nations, 2015). The project is most closely tied to SDG 16, Peace, Justice and Strong Institutions, particularly Target 16.6, which calls for effective, accountable, and transparent institutions at all levels, and Target 16.10, which aims to ensure public access to information. Automated routing, status tracking, and an audit trail make the Sangguniang Panlungsod&#039;s legislative work easier to monitor and account for, while the publication module and the PKI digital signature and SHA-256 verification help ensure that approved ordinances and resolutions released to the public are authentic and unaltered.</p><p>The project further relates to SDG 9, Industry, Innovation and Infrastructure, because it brings AI-supported drafting, classification, summarization, and speech-to-text tools into the daily operations of a local government office. It also contributes to SDG 12, Responsible Consumption and Production, specifically Target 12.5 on reducing waste generation, because replacing printed agendas, multiple photocopies, and paper-based minutes with digital records reduces the paper the office consumes and discards.</p><h2>1.2 Purpose and Description</h2><p>This capstone project aims to address the inefficiencies of paper-based legislative workflows in the Sangguniang Panlungsod of Santiago City. Specifically, it seeks to reduce long approval times, prevent missing or duplicated documents, improve visibility of each document’s approval status, and widen access to legislative outputs. To achieve this, the researchers developed E-Legis, a web-based legislative workflow and document management system.</p><p>The system utilizes AI-supported document processing and a PKI-based document signing and integrity system that combines digital certificates, SHA-256 hashing, and QR code verification to support the legislative work of the Sangguniang Panlungsod. The AI features help council members prepare bills and resolutions, classify and summarize documents, search legislative records, and transcribe recorded sessions, while the digital signatures prove who signed each approved ordinance and resolution and that it remains unaltered. Together, these features support faster processing, better monitoring of document status, and more transparent and accountable legislative work.</p><p>The system is designed for four primary users, each with specific roles:</p><p><strong>SP Secretariat (Administrator):</strong> Responsible for managing user accounts and access permissions, preparing agendas, scheduling sessions, tracking the routing and approval status of legislative documents, publishing ordinances and resolutions, generating reports, monitoring the audit trail and document verification alerts, and designating which officials are authorized to sign legislative documents.</p><p><strong>Presiding Officer:</strong> Responsible for reviewing and approving agendas, facilitating sessions through the tablet-based interface, approving legislative documents routed for final action, and, as an authorized signer, digitally signing approved ordinances and resolutions.</p><p><strong>Council Members:</strong> Responsible for drafting bills and resolutions using the AI Draft Assistant, viewing approved agendas and legislative documents, recording attendance, casting electronic votes during sessions, sharing finalized documents protected by SHA-256 hash-based verification, and verifying signed documents through their QR codes.</p><p><strong>Mayor’s Office:</strong> Responsible for submitting ordinances, requests, and executive orders to the Sanggunian and monitoring the status of the submitted documents.</p><p>In addition to these four user types, E-Legis recognizes the designation of <strong>Authorized Signer</strong>. This is not a separate account type but a signing permission that the SP Secretariat grants to the officials who legally sign legislative documents, such as the Presiding Officer and the Secretary to the Sanggunian. Each authorized signer is issued a personal digital certificate and a public–private key pair and is the only user who can digitally sign the documents assigned to them. The user who creates or uploads a bill does not automatically become its signer, and the SP Secretariat, although it manages users and signer designations, never receives or uses a signer’s private key.</p><p>The following are the highlights of the system:</p><p><strong>User Management and Role-Based Access-</strong> Creates and manages user accounts for the SP Secretariat, Presiding Officer, council members, and the Mayor’s Office. Each role can access only the modules and records it needs to perform its tasks, and the role that uploads or creates a document is kept separate from the authorized signer who signs it.</p><p><strong>Legislative Document Management-</strong> Allows users to draft, upload, store, and retrieve ordinances, resolutions, committee reports, and supporting files, with version control that numbers every revision and locks a version once it has been digitally signed.</p><p><strong>Digital Workflow Automation-</strong> Routes each document through its approval stages, from submission and committee review to Presiding Officer approval and publication, and records the current status of every document.</p><p><strong>Session Management-</strong> Supports session scheduling, agenda presentation through a tablet-based interface, attendance monitoring, electronic voting, and recording of session minutes.</p><p><strong>AI-Driven Document Processing-</strong> Provides an AI Draft Assistant that helps council members prepare bills and resolutions, automatic document classification and summarization, smart search, and speech-to-text transcription of session recordings.</p><p><strong>PKI Digital Signing-</strong> Extends the existing Sign function so that clicking Sign Document starts a PKI-based signing process. The system verifies that the user is an authorized signer, re-authenticates the signer, computes the SHA-256 hash of the final document, signs it with the signer’s private key, adds a visible signature block to the PDF, stores the hash and signature records in MySQL, and locks the signed version.</p><p><strong>SHA-256 Document Integrity Verification-</strong> Recomputes the SHA-256 hash of a document and verifies its digital signature against the signer’s certificate. The result is shown as Document Integrity Verified, Document Has Been Modified, or Digital Signature Invalid, and any problem alerts the document’s author and is recorded together with the last user who modified the document.</p><p><strong>QR Code Document Verification-</strong> Prints a QR code on every signed PDF. Scanning the code opens the E-Legis verification page, which shows the document ID, version, signer, date of signing, and current verification status of the document.</p><p><strong>Audit Trail-</strong> Records every action on a legislative document, including its creation, edits, approvals, signing attempts, signatures, and verifications, together with the user, the date and time, and the result.</p><p><strong>Notifications and Alerts-</strong> Sends real-time reminders for upcoming sessions, pending approvals, document status updates, and tamper alerts.</p><p><strong>Publication and Reporting-</strong> Maintains a local ordinance registry and generates PDF reports such as session, attendance, and document tracking reports.</p><h2>1.3 Objectives of the Study</h2><p>The primary objective of this study is to develop E-Legis: Electronic Legislative Workflow and Document Management, a web-based system for the Sangguniang Panlungsod of Santiago City, Isabela, that integrates AI-supported document processing and PKI-based digital signing with SHA-256 document verification to streamline the drafting, routing, approval, and archiving of legislative documents, and at the same time to help the SP Secretariat, the Presiding Officer, and the council members manage sessions, attendance, and voting electronically.</p><p>Specifically, the researchers aim to:</p><p>1. Implement system functionality for the following:</p><p>a.	SP Secretariat (Administrator)</p><p>i. Manage user accounts, roles, and access permissions</p><p>ii. Prepare agendas and schedule sessions</p><p>iii. Track the routing and approval status of legislative documents</p><p>iv. Publish ordinances and resolutions and generate reports</p><p>v. Monitor the audit trail and document verification alerts</p><p>vi. Designate authorized signers and manage the status of their digital certificates</p><p>b.	Presiding Officer</p><p>i. Review and approve agendas</p><p>ii. Facilitate sessions through the tablet-based interface</p><p>iii. Approve legislative documents routed for final action</p><p>c.	Council Members</p><p>i. Draft bills and resolutions using the AI Draft Assistant</p><p>ii. View approved agendas and legislative documents</p><p>iii. Record attendance and cast electronic votes during sessions</p><p>iv. Share finalized documents protected by SHA-256 hash-based verification</p><p>v. Verify signed documents through their QR verification codes</p><p>d.	Mayor’s Office</p><p>i. Submit ordinances, requests, and executive orders</p><p>ii. Monitor the status of submitted documents</p><p>e.	Authorized Signers (Presiding Officer and Secretary to the Sanggunian)</p><p>i. Authenticate and digitally sign assigned documents using their own digital certificate and private key</p><p>ii. Apply a visible signature block and QR verification code to each signed PDF</p><p>iii. View the signing history and verification status of the documents they signed</p><p>2. Test the performance of the system during:</p><p>a.	Load Testing</p><p>b.	Performance Testing</p><p>3. Evaluate the performance of the AI-supported document processing features using the following criteria:</p><p>a.	Word Error Rate (WER) of Speech-to-Text Transcription</p><p>b.	Document Classification Accuracy</p><p>c.	Summarization Quality</p><p>d.	Processing Speed</p><p>4. Evaluate the quality of the system based on the ISO/IEC 25010 Software Quality Standard with the following criteria:</p><p>a.	Functional Suitability</p><p>b.	Performance Efficiency</p><p>c.	Compatibility</p><p>d.	Usability</p><p>e.	Reliability</p><p>f.	Security</p><p>g.	Maintainability</p><h2>1.4 Scope and Limitation of the Study</h2><p>This study covers the design, development, and evaluation of E-Legis for the Sangguniang Panlungsod of Santiago City, Isabela. The intended users are the SP Secretariat (system administrators), the Presiding Officer, the council members, and the Mayor’s Office. The system includes the following modules: user management; legislative document management; digital workflow and approval; session management with tablet mode, attendance tracking, and electronic voting; notifications; publication and reporting; and security, digital signing, and verification.</p><p>The AI Draft Assistant helps council members prepare bills, resolutions, and other legislative matters. Based on the user’s instructions, it suggests the structure and wording of the draft (such as the title, whereas clauses, and sections), which the author then reviews and edits before submission. The AI module also classifies uploaded documents, produces short summaries, supports smart search, and transcribes recorded sessions into text.</p><p>Signing authority in E-Legis is separate from document authorship. Council members, the Mayor’s Office, and Secretariat staff may create, upload, and edit drafts, but only users whom the SP Secretariat has designated as authorized signers and who hold a valid digital certificate can digitally sign a document. When an authorized signer clicks Sign Document, the system confirms the signer’s authorization, asks the signer to re-authenticate, computes the SHA-256 hash of the final version, creates a digital signature with the signer’s private key, adds a visible signature block and a QR verification code to the PDF, stores the hash and signature records in the MySQL database, marks the document as digitally signed, and locks that version. Any later change must be saved as a new version, which must be signed again.</p><p>Each time a signed document is opened or its QR code is scanned, and each time a council member opens a finalized document shared by another council member, the system recomputes the SHA-256 hash and verifies the digital signature. If the hash differs from the stored value, the system flags the document as modified; if the signature cannot be verified, it flags the signature as invalid. In either case, it sends an alert to the author and records in the audit trail the event and the last user who modified the document, which council members and the administrator can view.</p><p>The study also has the following limitations. E-Legis requires an internet or local network connection to operate. During internet or network interruptions, users cannot access documents, receive notifications, or record attendance and votes until the connection is restored. The accuracy of the AI-supported features depends on the quality of the input, since poorly scanned, incomplete, or inconsistent documents and noisy session recordings may produce inaccurate classifications, summaries, or transcripts. For this reason, all AI outputs serve only as suggestions and must be reviewed by authorized personnel before use.</p><p>The system uses PKI digital signatures and SHA-256 hashing to prove who signed a document and to detect changes to it. All document hashes, signatures, certificates, versions, and audit records are stored in the system’s own MySQL database; the system does not use a blockchain, distributed ledger, or smart contracts, and therefore incurs no transaction or gas fees. The digital certificates of the signers are issued by an internal certificate authority set up for E-Legis and are not yet accredited under the Philippine National Public Key Infrastructure (PNPKI). Signers’ private keys are never stored as plaintext; each key is kept in encrypted form and can be unlocked only with its owner’s passphrase. The visible signature image on the PDF serves only as a human-readable representation of the signature, so the authenticity of a document rests on its digital signature and SHA-256 hash, not on the image. E-Legis is designed specifically for the local legislative office of the Sangguniang Panlungsod of Santiago City and is not intended to serve as the general records system of other city departments or as a public-facing citizen portal. Lastly, the evaluation of the system is limited to the respondents from the Sangguniang Panlungsod of Santiago City and the Mayor’s Office.</p><p>&lt;br&gt;</p><h1>CHAPTER II</h1><p><strong>REVIEW OF RELATED LITERATURE AND STUDIES</strong></p><p>This chapter presents the literature and studies related to the development of E-Legis. Related literature covers policies, frameworks, and reviews, while related studies cover empirical research and developed systems. Each is divided into foreign and local sources. Every source is presented with its title, a discussion of its main points, and its relation to E-Legis. A synthesis of all the reviewed literature and studies is presented at the end of the chapter.</p><h2>2.1 Related Literature/ Theoretical Background</h2><h2>2.1.1 Foreign Related</h2><p><strong>The OECD Digital Government Policy Framework: Six Dimensions of a Digital Government</strong></p><p>The Organization for Economic Co-operation and Development states that digital government is not merely converting paper documents into electronic files but redesigning processes so that government works more effectively and is oriented to users’ needs (OECD, 2020). The framework describes six dimensions that characterize a fully digital government.</p><p>This study is related to E-Legis because it guides the researchers to redesign the legislative workflow rather than simply scan existing paper records. While many offices treat digitalization as the conversion of printed files into PDF copies, E-Legis rebuilds the legislative process itself through automated routing, electronic approval, and session management, so that the Sangguniang Panlungsod works more efficiently and serves its users better.</p><p><strong>How and Where Is Artificial Intelligence in the Public Sector Going? A Literature Review and Research Agenda</strong></p><p>Sousa et al. (2019) reviewed 59 studies on artificial intelligence (AI) in the public sector and found growing interest in using AI to improve government services, together with ethical and legal concerns about its use.</p><p>This study is related to E-Legis because it supports the design decision of the system to use AI only as a decision-support tool. While AI can speed up government work, the ethical and legal concerns raised in the review show that its outputs must not be accepted without checking. For this reason, every draft, classification, and summary generated by E-Legis is reviewed by authorized users before it is used.</p><p><strong>Implications of the Use of Artificial Intelligence in Public Governance: A Systematic Literature Review and a Research Agenda</strong></p><p>Zuiderwijk et al. (2021) found that while research on AI in public governance is growing, more empirical work, attention to ethics, and interdisciplinary collaboration are needed.</p><p>This study is related to E-Legis because it reinforces the need for the system to keep human oversight over its AI features and to evaluate them with actual users. Following this direction, E-Legis leaves the final decision on every AI output to the council members and the SP Secretariat, and its AI-supported features are evaluated using measurable criteria such as word error rate, classification accuracy, summarization quality, and processing speed.</p><p><strong>Natural Language Processing for the Legal Domain: A Survey of Tasks, Datasets, Models, and Challenges</strong></p><p>Ariai and Demartini (2024) analyzed 127 studies and identified the main natural language processing (NLP) tasks in law, including legal document summarization, text classification, named entity recognition, question answering, and judgment prediction.</p><p>This study is related to E-Legis because the NLP tasks it identifies align directly with the classification, summarization, and smart search features of the system. While the survey discusses these tasks for legal texts in general, E-Legis applies them specifically to ordinances, resolutions, and committee reports so that the legislative staff can find, understand, and organize documents faster.</p><p><strong>When Large Language Models Meet Law: Dual-Lens Taxonomy, Technical Advances, and Ethical Governance</strong></p><p>Shao et al. (2025) reviewed how large language models are applied to legal drafting, reasoning, and retrieval, and discussed risks such as inaccurate outputs and the need for governance.</p><p>This study is related to E-Legis because it informs the design of the AI Draft Assistant of the system. Since large language models may produce inaccurate outputs, the AI Draft Assistant only suggests the structure and wording of a bill or resolution, and the author must verify and edit the draft before it is submitted.</p><p><strong>Role-Based Access Control Models</strong></p><p>Sandhu et al. (1996) described role-based access control (RBAC), in which permissions are assigned to roles rather than to individual users, as a standard approach to managing multi-user access.</p><p>This study is related to E-Legis because the system applies RBAC to protect legislative records. Instead of giving every user the same rights, E-Legis assigns permissions to the roles of the SP Secretariat, the Presiding Officer, the council members, and the Mayor’s Office, so that each user can access only the functions appropriate to their role.</p><p><strong>ISO/IEC 25010: Systems and Software Quality Requirements and Evaluation (SQuaRE)</strong></p><p>The International Organization for Standardization (2011) defines a product quality model with eight characteristics: functional suitability, performance efficiency, compatibility, usability, reliability, security, maintainability, and portability.</p><p>This study is related to E-Legis because it provides the standard used to evaluate the quality of the system. E-Legis is evaluated using seven of these characteristics, namely functional suitability, performance efficiency, compatibility, usability, reliability, security, and maintainability, which are the most relevant to its users and purpose.</p><p><strong>World e-Parliament Report 2024</strong></p><p>The Inter-Parliamentary Union (2024) assessed the use of digital technology in parliaments worldwide using survey responses from 115 parliaments or chambers in 86 countries and supranational parliaments. The report found that most parliaments now have a multi-year digital strategy, that the use of artificial intelligence and cloud computing is increasing, that cybersecurity is a top priority, and that a digital divide is widening between richer and poorer parliaments.</p><p>This study is related to E-Legis because it shows that digital transformation is now a strategic concern of legislative bodies and that security must be built into such systems from the start. E-Legis reflects these findings by combining role-based access control, PKI digital signatures with SHA-256 hash verification, and an audit trail, and by offering a low-cost web-based system that a local legislative body can adopt without depending on large institutional resources.</p><p><strong>Secure Hash Standard (FIPS PUB 180-4)</strong></p><p>The National Institute of Standards and Technology (2015) specifies the secure hash algorithms, including SHA-256, which condense a message of any length into a fixed-size message digest. Because a change to the message will, with very high probability, produce a different digest, the digest can be used to check whether data has been altered.</p><p>This standard is related to E-Legis because it is the basis of the document verification feature of the system. E-Legis computes the SHA-256 hash of every finalized ordinance and resolution and compares it with a newly computed hash each time the document is opened, so that any modification is detected and reported to the author.</p><p><strong>Digital Signature Standard (FIPS PUB 186-5)</strong></p><p>The National Institute of Standards and Technology (2023) specifies the approved methods for generating and verifying digital signatures, including RSA, ECDSA, and EdDSA. A digital signature is generated with the signer’s private key and verified with the corresponding public key, which allows a verifier to detect unauthorized changes to the signed data and to confirm the identity of the signatory, supporting non-repudiation.</p><p>This standard is related to E-Legis because it is the basis of the PKI signing feature of the system. When an authorized signer signs a document, E-Legis signs the SHA-256 hash of the document with the signer’s private key, and the signature is later verified with the signer’s public key to prove who signed the document and that it has not been altered.</p><p><strong>Internet X.509 Public Key Infrastructure Certificate Profile (RFC 5280)</strong></p><p>Cooper et al. (2008) defined the format and contents of X.509 version 3 public key certificates and certificate revocation lists. A certificate binds a public key to the identity of its holder, while its validity period and revocation status allow relying parties to check whether the certificate can still be trusted.</p><p>This literature is related to E-Legis because the system issues each authorized signer an X.509 digital certificate that links the signer’s name, position, and public key. Before a signature is accepted or verified, E-Legis checks that the certificate is within its validity period and has not been revoked.</p><p><strong>Manifesto for Agile Software Development</strong></p><p>Beck et al. (2001) stated the values of Agile software development, which favor individuals and interactions over processes and tools, working software over comprehensive documentation, customer collaboration over contract negotiation, and responding to change over following a plan.</p><p>This literature is related to E-Legis because it is the foundation of the development methodology used in this study. The researchers built E-Legis in short iterations, delivered working modules for review, and adjusted the features according to the feedback of the SP Secretariat, the council members, and the other users.</p><h2>2.1.2 Local Related</h2><p><strong>Local Government Code of 1991 (Republic Act No. 7160)</strong></p><p>The Local Government Code defines the Sangguniang Panlungsod as the legislative body of a city, responsible for enacting ordinances and approving resolutions (Republic Act No. 7160, 1991). It establishes the legislative processes, such as referral, deliberation, approval, and veto.</p><p>This literature is related to E-Legis because it defines the legislative process that the system digitizes. The workflow module of E-Legis follows the same stages set by the Code, from the referral of a measure to a committee up to its approval, veto, or override, ensuring that the digital process remains consistent with the law.</p><p><strong>E-Governance Act (Republic Act No. 12254)</strong></p><p>The E-Governance Act requires national agencies and local government units to adopt digital, interoperable, and secure systems to improve transparency and service delivery (Republic Act No. 12254, 2025). The Philippine News Agency (2025) reported that the law institutionalizes the government’s shift to e-governance.</p><p>This literature is related to E-Legis because it provides the legal mandate for the digital transformation of local government offices. E-Legis directly supports this mandate at the level of a city legislative office by replacing paper-based legislative processes with a secure digital system.</p><p><strong>E-Government Master Plan</strong></p><p>The Department of Information and Communications Technology (2024) outlines the national plan for digital government services, which the E-Governance Act requires to be updated regularly.</p><p>This literature is related to E-Legis because the system aligns with the plan’s direction toward digital and interoperable government processes. By providing digital document management and workflow automation for the Sangguniang Panlungsod, E-Legis contributes to the goals of the plan at the local level.</p><p><strong>Ease of Doing Business and Efficient Government Service Delivery Act (Republic Act No. 11032)</strong></p><p>Republic Act No. 11032 (2018) requires government offices to streamline processes, set processing timeframes, and reduce red tape.</p><p>This literature is related to E-Legis because the automated routing and status tracking of the system help the Sangguniang Panlungsod shorten processing time and make delays visible. While manual routing makes it difficult to know where a document is and how long it has been pending, E-Legis records every stage of the approval process, supporting the law’s goal of reducing red tape.</p><p><strong>Philippine Development Plan 2023–2028</strong></p><p>The Philippine Development Plan identifies the digital transformation of government, including digital transactions and data-driven governance, as a national priority (National Economic and Development Authority, 2023).</p><p>This literature is related to E-Legis because the system contributes to this national priority by eliminating paper-based legislative processes and by providing data, such as attendance, voting, and document status reports, that support better decision-making in the Sangguniang Panlungsod.</p><p><strong>Data Privacy Act of 2012 (Republic Act No. 10173)</strong></p><p>The Data Privacy Act sets rules for collecting, processing, and protecting personal information in public and private organizations (Republic Act No. 10173, 2012).</p><p>This literature is related to E-Legis because the system processes personal information such as user accounts, attendance data, and votes. To comply with the law, E-Legis applies role-based access control, password encryption, and audit logging to protect the personal information it stores.</p><p><strong>Electronic Commerce Act of 2000 (Republic Act No. 8792)</strong></p><p>Republic Act No. 8792 (2000) aims to recognize the authenticity and reliability of electronic data messages and electronic documents and to promote the universal use of electronic transactions in government and by the general public.</p><p>This law is related to E-Legis because it supports the use of electronic documents and electronic signatures in place of paper and wet signatures in government work. It gives the Sangguniang Panlungsod a legal basis for handling agendas, ordinances, and resolutions in electronic form and for signing them digitally within the system.</p><p><strong>Institutionalizing the Certification Scheme for Digital Signatures (Executive Order No. 810)</strong></p><p>Executive Order No. 810 (2009) institutionalized a certification scheme for digital signatures in government, designated the National Computer Center as the root and government certification authority, and directed government agencies to apply digital signatures in their e-government services to ensure the confidentiality, authenticity, integrity, and non-repudiation of electronic transactions.</p><p>This order is related to E-Legis because it supports the use of PKI digital signatures for official government documents. E-Legis applies the same principles to the signing of ordinances and resolutions, and its signing module can later be linked to the government certification authority, as recommended in Chapter VI.</p><p><strong>National Archives of the Philippines Act of 2007 (Republic Act No. 9470)</strong></p><p>Republic Act No. 9470 (2007) gives the highest priority to the safeguarding, protection, and preservation of public documents and records as instruments of efficient and effective governance. It covers the archival and records management programs of all branches of government, whether national or local.</p><p>This law is related to E-Legis because legislative records of a local government are public records that must be kept safe and orderly. The legislative archive, audit trail, and scheduled database backups of E-Legis support the proper keeping of these records, while the rules on the transfer and disposal of records continue to apply.</p><p><strong>Department of Information and Communications Technology Act of 2015 (Republic Act No. 10844)</strong></p><p>Republic Act No. 10844 (2016) created the Department of Information and Communications Technology as the primary agency for planning, developing, and promoting the national ICT development agenda. It declares as State policy the use of ICT to improve key public services.</p><p>This law is related to E-Legis because it shows that national policy encourages government offices to adopt ICT systems that improve their services. E-Legis is consistent with this policy since it applies ICT to the document processing, session, and reporting functions of a city legislative body.</p><p><strong>Rules on Electronic Evidence (A.M. No. 01-7-01-SC)</strong></p><p>The Supreme Court of the Philippines (2001) issued the Rules on Electronic Evidence, which govern the admissibility and proof of electronic documents in court proceedings.</p><p>These rules are related to E-Legis because finalized legislative documents may need to be shown as authentic. The SHA-256 hash verification and the audit trail of E-Legis record who acted on a document and whether it was changed, which helps keep the electronic record dependable.</p><h2>2.2 Related Studies</h2><h2>2.2.1 Foreign Related</h2><p><strong>User Acceptance of Intergovernmental Services: An Example of an Electronic Document Management System</strong></p><p>Hung et al. (2009) studied 186 users of an electronic document management system (EDMS) in Taiwan and found that perceived usefulness, ease of use, training, compatibility, self-efficacy, and facilitating conditions influence users’ intention to adopt the system.</p><p>This study is related to E-Legis because it shows that a document management system must be easy to use and supported by user training to be accepted. For this reason, E-Legis was designed with a simple interface that works on both desktops and tablets, and the researchers consider user orientation an important part of deploying the system to the legislative staff and council members.</p><p><strong>An O(ND) Difference Algorithm and Its Variations</strong></p><p>Myers (1986) presented an efficient algorithm for finding the minimum differences between two texts, which remains the basis of many text comparison and version control tools.</p><p>This study is related to E-Legis because the system uses this approach to show the changes between draft versions of a legislative document during review. Instead of comparing printed drafts manually, council members and the Secretariat can see exactly which words were added or removed in each revision.</p><p><strong>Implementation of an Automatic Meeting Minute Generation System Using YAMNet with Speaker Identification and Keyword Prompts</strong></p><p>Lu and Wang (2024) developed a system that automatically generates meeting minutes using speaker identification and speech-to-text recognition and reported high accuracy.</p><p>This study is related to E-Legis because it supports the speech-to-text feature of the system, which transcribes recorded sessions to assist the Journals Section. While the Journals Section currently encodes audio recordings into transcripts manually, E-Legis provides a draft transcript that the staff can edit and finalize, reducing the time spent on transcription.</p><p><strong>Electronic Voting Systems: Requirements, Design, and Implementation</strong></p><p>Qadah and Taha (2007) showed that computer-based voting reduces errors and simplifies the counting process compared with manual voting.</p><p>This study is related to E-Legis because it is the basis for the electronic voting feature used by council members during sessions. Instead of counting votes manually, E-Legis records each vote through the tablet-based interface and computes the results automatically.</p><p><strong>CaseEncoder: A Knowledge-Enhanced Pre-Trained Model for Legal Case Encoding</strong></p><p>Ma et al. (2023) developed a pre-trained language model that represents legal documents more accurately for retrieval tasks, showing that domain-aware models improve legal search.</p><p>This study is related to E-Legis because it relates to the smart search feature of the system, which helps users locate ordinances, resolutions, and other legislative records more quickly than searching through physical files.</p><p><strong>Joint Learning for Legal Text Retrieval and Textual Entailment</strong></p><p>Nguyen et al. (2023) improved legal text retrieval by jointly learning which documents are relevant and whether they support a given statement.</p><p>This study is related to E-Legis because it demonstrates techniques for retrieving relevant provisions from large legal collections, similar to the search function that E-Legis provides for ordinances and resolutions.</p><p><strong>SHA-256 Hashing for Digital Document Verification</strong></p><p>Abidin and Munggaran (2025) tested SHA-256 hashing for verifying the integrity of digital documents and showed that comparing a document’s hash with its stored hash reliably detects tampering.</p><p>This study is related to E-Legis because the system adopts the same SHA-256 hashing and comparison technique to verify its finalized legislative documents. Unlike the referenced study, which records the hashes on a blockchain platform, E-Legis stores the hashes in its own MySQL database without any blockchain or transaction fees and pairs each hash with a PKI digital signature that identifies the signer. When a mismatch is found, the system alerts the author and records the last user who modified the document.</p><p><strong>ParlTech: Transformation Framework for the Digital Parliament</strong></p><p>Koryzis et al. (2021) surveyed parliamentary experts, including members of parliament and parliamentary administrators, to define a framework for the digital parliament. The 32 respondents from 25 countries gave the highest priority to data, processes, and people, and they identified bureaucratic culture and resistance to change as the main barriers to digital transformation.</p><p>This study is related to E-Legis because it shows that a digital system for a legislative body should focus on processes and data while involving its users. E-Legis addresses these priorities by digitizing the legislative workflow and records, and it responds to the barrier of resistance to change by keeping the interface simple for the SP Secretariat and the council members.</p><p><strong>Crowdsourcing the Digital Parliament</strong></p><p>Fitsilis and Mikros (2025) examined the Hellenic Optical Character Recognition Team, a crowdsourcing initiative for processing and analyzing parliamentary data. Based on survey findings, the study reported the profiles and motivations of the participants and concluded that the initiative improved the accessibility and transparency of parliamentary data.</p><p>This study is related to E-Legis because both aim to make legislative records easier to access and use. E-Legis stores documents in an organized database, classifies and summarizes them with the help of AI, and indexes them for smart search, so that the records of the Sangguniang Panlungsod can be found quickly.</p><p><strong>Diversification of Legislation Editing Open Software (LEOS) Using Software Agents</strong></p><p>Leventis et al. (2021) worked on Legislation Editing Open Software, a free tool for editing legislative texts in a structured and standardized format, to turn the parliamentary control records of the Hellenic Parliament into open legal data. They emphasized that the accessibility and reuse of legal data are important for transparency, accountability, and public trust.</p><p>This study is related to E-Legis because it treats legislative drafting and records as structured data rather than scattered paper files. E-Legis follows the same idea by recording the metadata of every document, showing the differences between draft versions, and keeping an audit trail, which improves transparency and accountability in the legislative process.</p><h2>2.2.2 Local Related</h2><p><strong>E-Governance at the Local Government Level in the Philippines: An Assessment of City Government Websites</strong></p><p>Siar (2007) found that although local government units had increased their online presence, they did not use their websites as effective e-governance tools.</p><p>This study is related to E-Legis because it shows that online presence alone does not improve internal government processes such as legislation. While city websites mainly publish information, E-Legis focuses on the internal work of the legislative office, including drafting, routing, approval, and session management.</p><p><strong>Towards a Digital Governance Divide Index: Evaluating City Government Websites in the Philippines</strong></p><p>Lagura (2025) evaluated the websites of 33 Philippine cities and found continuing problems in content quality, privacy, inclusiveness, and public participation.</p><p>This study is related to E-Legis because it confirms that many city governments still need systems that go beyond informational websites. E-Legis answers this need by providing a working digital platform for the legislative operations of the Sangguniang Panlungsod.</p><p><strong>E-Governance in Paracale: A Digital Transformation for Improved Public Service Delivery and Citizen Engagement</strong></p><p>Dela Peña (2025) evaluated the e-government services of the municipality of Paracale, Camarines Norte, using the ISO/IEC 25010 quality model.</p><p>This study is related to E-Legis because it supports the use of ISO/IEC 25010 in evaluating local government systems. Following the same approach, E-Legis is evaluated by its users based on the quality characteristics of the standard.</p><p><strong>Towards Digital Legislation: Readiness of the Sangguniang Bayan of LGU Motiong for Paperless Sessions</strong></p><p>Gabuya (2025) found that the Sangguniang Bayan of Motiong had the devices and basic digital skills needed for digital sessions but still relied on printed documents, resulting in printing costs, delayed approvals, and lost documents.</p><p>This study is related to E-Legis because it shows that local legislative offices are ready for a digital legislative system. While the Sangguniang Bayan of Motiong still relied on printed documents despite having the necessary devices, E-Legis provides the platform that allows a legislative office to conduct its sessions and process its documents without paper.</p><p><strong>eDALAYON: A Document Management and Monitoring System for the Department of the Interior and Local Government</strong></p><p>Rodriguez et al. (2024) developed a document management and monitoring system for the Department of the Interior and Local Government (DILG) and reported that conventional practices in government offices cause delays, loss of files, and lack of transparency.</p><p>This study is related to E-Legis because both systems address delays, loss of files, and lack of transparency in government offices. While eDALAYON manages general government documents, E-Legis is designed specifically for legislative documents and includes session management, electronic voting, and document verification.</p><p><strong>Electronic Document Management System for Local Area Network-Based Organizations</strong></p><p>Gamido et al. (2023) developed an electronic document management system (EDMS) for LAN-based organizations and found that it significantly improved the archiving and retrieval of documents.</p><p>This study is related to E-Legis because it supports the LAN-accessible design of the system within the city hall network, which allows the legislative staff and council members to archive and retrieve documents quickly.</p><p><strong>Development and Evaluation of an Enterprise-Level Information System for Digital Governance in Philippine SUCs</strong></p><p>Lagman et al. (2025) developed an information system for Philippine state universities and colleges using the Agile methodology and evaluated it using ISO/IEC 25010.</p><p>This study is related to E-Legis because it serves as a methodological model for the system. E-Legis uses the same development approach, the Agile methodology, and the same evaluation standard, ISO/IEC 25010.</p><p><strong>LeMTrac: Legislative Management and Tracking System</strong></p><p>Pandes et al. (2018) developed LeMTrac for the municipal governments of Nabua and Bula, Camarines Sur, to track legislative documents, and end users gave it a high usability rating.</p><p>This study is related to E-Legis because LeMTrac is the closest local counterpart of the system. However, LeMTrac focuses on tracking legislative documents and does not include session management, AI-supported processing, or hash-based verification, which E-Legis provides in one platform.</p><p><strong>Design of a Legislative Records Management System: A Phased Intervention for the Sangguniang Bayan of Garchitorena</strong></p><p>Valiente (2026) identified recurring problems in manual legislative record-keeping, including slow data access, unavailable records, risk of losing documents, and inefficient retrieval, and proposed a records management system.</p><p>This study is related to E-Legis because the problems it identified are the same ones E-Legis addresses. While the study proposed a records management system for a Sangguniang Bayan, E-Legis goes further by automating the approval workflow and the conduct of legislative sessions.</p><p><strong>Evaluating Workflow Automation Efficiency in a Government Agency in the Philippines</strong></p><p>Cabaobao et al. (2024) used the Technology Acceptance Model to evaluate workflow automation tools in a Philippine government agency and found improvements in efficiency, speed, and collaboration, along with challenges such as employee resistance and integration issues.</p><p>This study is related to E-Legis because it highlights both the benefits of workflow automation and the challenges of adopting it. These findings show the need for user orientation when deploying E-Legis so that the legislative staff can adjust to the new digital workflow.</p><p><strong>Province of Laguna Legislative Management and Tracking System with the Application of Latent Dirichlet Allocation (LDA) Algorithm</strong></p><p>Cruz and Balahadia (2023) applied Latent Dirichlet Allocation (LDA) to identify themes in the ordinances and resolutions of Laguna. It is one of the few Philippine studies that applies intelligent text processing to legislative documents.</p><p>This study is related to E-Legis because it applies intelligent text processing to legislative documents, similar to the AI classification and search features of the system. However, the Laguna system does not manage sessions or approvals, which E-Legis includes.</p><p><strong>Barangay Information Management System with Automated Mobile Messaging for Improved Community Engagement</strong></p><p>Rivas (2026) developed a barangay information system with automated mobile messaging and showed that automated notifications improve communication in local governance.</p><p>This study is related to E-Legis because it supports the notification and alert module of the system, which sends reminders for upcoming sessions, pending approvals, document updates, and tamper alerts to its users.</p><h2>Synthesis</h2><p>Based on the reviewed literature and studies, local legislative offices in the Philippines play an important role in governance, but many of them still rely on paper-based processes. The local literature establishes both the legal basis and the obligation for E-Legis. The Local Government Code defines the legislative process to be digitized, while the E-Governance Act, the E-Government Master Plan, RA 11032, and the Philippine Development Plan require government offices to adopt efficient digital systems. The Data Privacy Act sets the security requirements that the system must meet, while the Electronic Commerce Act and Executive Order No. 810 recognize electronic signatures and direct government agencies to use digital signatures in their e-government services.</p><p>The foreign literature shows that digital government requires process redesign, not only digitization (OECD, 2020), and that AI can support legal and legislative work through classification, summarization, drafting, and retrieval (Ariai &amp; Demartini, 2024; Shao et al., 2025), provided that humans remain in control (Sousa et al., 2019; Zuiderwijk et al., 2021). Role-based access control (Sandhu et al., 1996), digital signatures and X.509 certificates (National Institute of Standards and Technology, 2023; Cooper et al., 2008), and ISO/IEC 25010 provide established standards for securing and evaluating such a system.</p><p>The local studies confirm that Philippine local governments, including legislative offices, still face delays, lost files, and limited transparency due to manual processes (Rodriguez et al., 2024; Gabuya, 2025; Valiente, 2026). Existing local systems such as LeMTrac, eDALAYON, and the Laguna system each address only part of the problem, such as tracking, general document management, or topic modeling. The foreign studies, on the other hand, show that EDMS adoption depends on usability and training (Hung et al., 2009) and provide proven techniques for the main features of E-Legis: text differencing for version comparison (Myers, 1986), speech-to-text for minutes (Lu &amp; Wang, 2024), electronic voting (Qadah &amp; Taha, 2007), legal text retrieval (Ma et al., 2023; Nguyen et al., 2023), and SHA-256 document verification (Abidin &amp; Munggaran, 2025), which E-Legis strengthens with PKI digital signatures stored in MySQL instead of a blockchain. However, these techniques were studied separately and not in the context of a Philippine local legislative office.</p><p>These findings support the development of E-Legis. No reviewed system combines workflow automation, session management with electronic voting, AI-assisted drafting and search, and PKI digital signing with SHA-256 hash-based verification in one platform for a city legislative office. E-Legis was developed to fil', 'Team-Panorth.docx', 'revision_26be71367864a7e1_v4_f2548a45c20249d1_Team-Panorth.docx', '6e3495095d67c5eaaac2a3dc3e521a8a74292a1f1a3bb0ab23e274f2d314c5f6', '7486bc1d2df7e69c', 'isu', '2026-10-02 19:52:10.000000', NULL, NULL, '26be71367864a7e1', 'Revision v4');
